// block that a NodeBlock says is taken. The controller keeps no other state.
func buildPool(spec *remediationv1alpha1.IPPoolSpec, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock) (*buddy.Pool, []string) {
	p := buddy.NewPool()
	cidrs, problems := validCIDRs(spec, nodes)
	for _, c := range cidrs {
		if err := p.AddCIDR(c, spec.MinBlockSize, spec.MaxBlockSize); err != nil {
			problems = append(problems, err.Error())
		}
	}
	sorted := append([]remediationv1alpha1.NodeBlock(nil), blocks...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Spec.CIDR < sorted[j].Spec.CIDR })
	for i := range sorted {
		b := &sorted[i]
		if blockPhase(b) == remediationv1alpha1.NodeBlockReleased {
			continue
		}
		if _, err := p.Reserve(b.Spec.CIDR, b.Spec.NodeName); err != nil {
			problems = append(problems, fmt.Sprintf("NodeBlock %s (%s) cannot be placed in the pool: %v", b.Name, b.Spec.CIDR, err))
		}
	}
	return p, problems
}

// planPool decides which blocks to create: an initial block for every node that
// has none, and growth for nodes that are running low. It never changes the API.
func planPool(spec *remediationv1alpha1.IPPoolSpec, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock) *poolPlan {
	p, problems := buildPool(spec, nodes, blocks)
	plan := &poolPlan{Pool: p, Problems: problems}

	byNode := map[string][]remediationv1alpha1.NodeBlock{}
	for _, b := range blocks {
		if blockPhase(&b) != remediationv1alpha1.NodeBlockReleased {
			byNode[b.Spec.NodeName] = append(byNode[b.Spec.NodeName], b)
		}
	}

	sorted := append([]corev1.Node(nil), nodes...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
	minAddrs := 1 << (32 - spec.MinBlockSize)

	for i := range sorted {
		n := &sorted[i]
		if !n.DeletionTimestamp.IsZero() {
			continue
		}
		owned := byNode[n.Name]
		pods := allocatablePods(n)

		if len(owned) == 0 {
			size := initialBlockSize(spec, pods)
			b, err := p.Allocate(size, n.Name)
			if err != nil {
				plan.Exhausted = true
				plan.Problems = append(plan.Problems, fmt.Sprintf("no initial block for node %s: %v", n.Name, err))
				continue
			}
			plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: b.CIDR, Reason: reasonInitial})
			plan.Pending = true
			continue
		}

		// Only one change in flight per node: wait for Pending and Draining
		// blocks to settle before judging capacity.
		inFlight := false
		capacity, used := 0, 0
		var active []*buddy.Block
		for i := range owned {
			switch blockPhase(&owned[i]) {
			case remediationv1alpha1.NodeBlockActive:
				capacity += usableAddresses(blockAddresses(owned[i].Spec.CIDR))
				used += owned[i].Status.UsedAddresses
				if blk := p.Find(owned[i].Spec.CIDR); blk != nil {
					active = append(active, blk)
				}
			case remediationv1alpha1.NodeBlockPending, remediationv1alpha1.NodeBlockDraining:
				inFlight = true
			}
		}
		if inFlight {
			plan.Pending = true
			continue
		}
		if !needsGrowth(spec, capacity, used) {
			continue
		}

		headroom := capacityCap(spec, pods) - capacity
		target := growthTarget(spec, capacity, headroom, minAddrs)
		if target == 0 {
			plan.Problems = append(plan.Problems, fmt.Sprintf("node %s reached its capacity cap (%d%% of %d pods)", n.Name, spec.CapacityCapPercent, pods))
			continue
		}

		// Prefer taking the buddy of a block the node already owns: the two
		// halves then aggregate into one route. Largest block first, and only
		// if the buddy does not overshoot the target.
		sort.Slice(active, func(a, b int) bool { return active[a].Addresses() > active[b].Addresses() })
		grown := false
		for _, blk := range active {
			if blk.Addresses() > target || usableAddresses(blk.Addresses()) > headroom {
				continue
			}
			if bd, err := p.AllocateBuddyOf(blk, n.Name); err == nil {
				plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: bd.CIDR, Reason: reasonGrowInPlace})
				grown = true
				break
			}
		}
		if grown {
			plan.Pending = true
			continue
		}

		got, err := p.AllocateDemand(target-blockOverhead, n.Name)
		if err != nil {
			plan.Exhausted = true
			plan.Problems = append(plan.Problems, fmt.Sprintf("cannot grow node %s: %v", n.Name, err))
			continue
		}
		for _, b := range got {
			plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: b.CIDR, Reason: reasonGrow})
		}
		plan.Pending = true
	}
	return plan
}

func joinProblems(p []string) string {
	return strings.Join(p, "; ")
}
