	if err != nil {
		return fmt.Errorf("list routes: %w", err)
	}
	wantSet := map[Route]bool{}
	for _, r := range want {
		wantSet[r] = true
	}
	haveSet := map[Route]bool{}
	for _, r := range have {
		haveSet[r] = true
	}

	var errs []error
	for _, r := range have {
		if !wantSet[r] {
			if err := a.Routes.Delete(r); err != nil {
				errs = append(errs, fmt.Errorf("delete route %s: %w", r.Dst, err))
