		if err := a.Client.Get(ctx, types.NamespacedName{Name: name}, &b); err != nil {
			return client.IgnoreNotFound(err)
		}
		if !mutate(&b) {
			return nil
		}
		return a.Client.Status().Update(ctx, &b)
	})
