		if err := a.updateStatus(ctx, name, func(cur *remediationv1alpha1.NodeBlock) bool {
			changed := false
			if promoting && phaseOf(cur) == remediationv1alpha1.NodeBlockPending {
				now := metav1.NewTime(a.now())
				cur.Status.Phase = remediationv1alpha1.NodeBlockActive
				cur.Status.LastTransitionTime = &now
				changed = true
				logger.Info("block active", "cidr", cur.Spec.CIDR)
			}
			if cur.Status.UsedAddresses != n {
				cur.Status.UsedAddresses = n
				changed = true
			}
			return changed
		}); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}
