	if p.Type != "ptp" || p.IPAM.Type != "host-local" || p.IPMasq == nil || *p.IPMasq {
		t.Fatalf("plugin: %+v", p)
	}
	// One inner array holding every block, in address order.
	if len(p.IPAM.Ranges) != 1 || len(p.IPAM.Ranges[0]) != 2 ||
