21		"net"
22		"slices"
23		"strings"
24	
25		corev1 "k8s.io/api/core/v1"
26	
27		remediationv1alpha1 "CS331-CN-Project-1/operator/api/v1alpha1"
28		"CS331-CN-Project-1/operator/internal/controller/ipam/buddy"
29	)
30	
31	// Why a block was planned.
32	const (
33		reasonInitial     = "initial"
34		reasonGrow        = "grow"
35		reasonGrowInPlace = "grow-in-place"
36	)
37	
38	// plannedBlock is a block the controller decided to give a node.
39	type plannedBlock struct {
40		NodeName string
41		CIDR     string
42		Reason   string
43	}
44	
45	// poolPlan is the outcome of one planning pass over a pool.
46	type poolPlan struct {
47		// Pool is the buddy forest rebuilt from the existing NodeBlocks plus the
48		// planned blocks.
49		Pool *buddy.Pool
50		// New lists the blocks to create.
51		New []plannedBlock
52		// Problems are conditions a human should look at (bad CIDRs, exhaustion).
53		Problems []string
54		// Exhausted is true when a node needed space the pool could not give.
55		Exhausted bool
56		// Pending is true while some node has a block that is not yet Active.
57		Pending bool
58	}
59	
60	// withDefaults fills zero values with the documented defaults, so planning
61	// behaves the same whether or not the API server applied them.
62	func withDefaults(in remediationv1alpha1.IPPoolSpec) remediationv1alpha1.IPPoolSpec {
63		s := in
64		def := func(v *int, d int) {
65			if *v == 0 {
66				*v = d
67			}
68		}
69		def(&s.MinBlockSize, 28)
70		def(&s.MaxBlockSize, 22)
71		def(&s.ExpandThresholdPercent, 80)
72		def(&s.TriggerFloor, 8)
73		def(&s.GrowthPercent, 50)
74		def(&s.CapacityCapPercent, 120)
75		def(&s.InitialBlockPercent, 25)
76		return s
77	}
78	
79	func allocatablePods(n *corev1.Node) int {
80		if q, ok := n.Status.Allocatable[corev1.ResourcePods]; ok && q.Value() > 0 {
81			return int(q.Value())
82		}
83		return defaultAllocatablePods
84	}
85	
86	// blockPhase treats a missing phase as Pending: the controller creates the
87	// object and then sets the phase, and a crash in between must not matter.
88	func blockPhase(b *remediationv1alpha1.NodeBlock) string {
89		if b.Status.Phase == "" {
90			return remediationv1alpha1.NodeBlockPending
91		}
92		return b.Status.Phase
93	}
94	
95	func blockAddresses(cidr string) int {
96		_, n, err := net.ParseCIDR(cidr)
97		if err != nil {
98			return 0
99		}
100		ones, bits := n.Mask.Size()
101		return 1 << (bits - ones)
102	}
103	
104	// validCIDRs returns the pool CIDRs that may be used, in order, and a problem
105	// for each one that may not: unparseable, overlapping a reserved range, or
106	// containing a node's InternalIP (which would silently black-hole traffic).
107	func validCIDRs(spec *remediationv1alpha1.IPPoolSpec, nodes []corev1.Node) (ok, problems []string) {
108		var reserved []*net.IPNet
109		for _, r := range spec.ReservedCIDRs {
110			if _, n, err := net.ParseCIDR(r); err == nil {
111				reserved = append(reserved, n)
112			}
113		}
114		for _, c := range spec.CIDRs {
115			_, n, err := net.ParseCIDR(c)
116			if err != nil {
117				problems = append(problems, fmt.Sprintf("CIDR %q is invalid: %v", c, err))
118				continue
119			}
120			bad := ""
121			for _, r := range reserved {
122				if r.Contains(n.IP) || n.Contains(r.IP) {
123					bad = fmt.Sprintf("CIDR %s overlaps reserved range %s", c, r)
124					break
125				}
126			}
127			if bad == "" {
128				for i := range nodes {
129					for _, a := range nodes[i].Status.Addresses {
130						if a.Type != corev1.NodeInternalIP {
131							continue
132						}
133						if ip := net.ParseIP(a.Address); ip != nil && n.Contains(ip) {
134							bad = fmt.Sprintf("CIDR %s contains the InternalIP %s of node %s", c, a.Address, nodes[i].Name)
135						}
136					}
137				}
138			}
139			if bad != "" {
140				problems = append(problems, bad)
141				continue
142			}
143			ok = append(ok, c)
144		}
145		return ok, problems
146	}
147	
148	// buildPool rebuilds the buddy forest from scratch: the pool CIDRs, minus every
149	// block that a NodeBlock says is taken. The controller keeps no other state.
150	func buildPool(spec *remediationv1alpha1.IPPoolSpec, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock) (*buddy.Pool, []string) {
151		p := buddy.NewPool()
152		cidrs, problems := validCIDRs(spec, nodes)
153		for _, c := range cidrs {
154			if err := p.AddCIDR(c, spec.MinBlockSize, spec.MaxBlockSize); err != nil {
155				problems = append(problems, err.Error())
156			}
157		}
158		sorted := append([]remediationv1alpha1.NodeBlock(nil), blocks...)
159		slices.SortFunc(sorted, func(a, b remediationv1alpha1.NodeBlock) int { return strings.Compare(a.Spec.CIDR, b.Spec.CIDR) })
160		for i := range sorted {
161			b := &sorted[i]
162			if blockPhase(b) == remediationv1alpha1.NodeBlockReleased {
163				continue
164			}
165			if _, err := p.Reserve(b.Spec.CIDR, b.Spec.NodeName); err != nil {
166				problems = append(problems, fmt.Sprintf("NodeBlock %s (%s) cannot be placed in the pool: %v", b.Name, b.Spec.CIDR, err))
167			}
168		}
169		return p, problems
170	}
171	
172	// planPool decides which blocks to create: an initial block for every node that
173	// has none, and growth for nodes that are running low. It never changes the API.
174	func planPool(spec *remediationv1alpha1.IPPoolSpec, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock) *poolPlan {
175		p, problems := buildPool(spec, nodes, blocks)
176		plan := &poolPlan{Pool: p, Problems: problems}
177	
178		byNode := map[string][]remediationv1alpha1.NodeBlock{}
179		for _, b := range blocks {
180			if blockPhase(&b) != remediationv1alpha1.NodeBlockReleased {
181				byNode[b.Spec.NodeName] = append(byNode[b.Spec.NodeName], b)
182			}
183		}
184	
185		sorted := append([]corev1.Node(nil), nodes...)
186		slices.SortFunc(sorted, func(a, b corev1.Node) int { return strings.Compare(a.Name, b.Name) })
187		minAddrs := 1 << (32 - spec.MinBlockSize)
188	
189		for i := range sorted {
190			n := &sorted[i]
191			if !n.DeletionTimestamp.IsZero() {
192				continue
193			}
194			owned := byNode[n.Name]
195			pods := allocatablePods(n)
196	
197			if len(owned) == 0 {
198				size := initialBlockSize(spec, pods)
199				b, err := p.Allocate(size, n.Name)
200				if err != nil {
201					plan.Exhausted = true
202					plan.Problems = append(plan.Problems, fmt.Sprintf("no initial block for node %s: %v", n.Name, err))
203					continue
204				}
205				plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: b.CIDR, Reason: reasonInitial})
206				plan.Pending = true
207				continue
208			}
209	
210			// Only one change in flight per node: wait for Pending and Draining
211			// blocks to settle before judging capacity.
212			inFlight := false
213			capacity, used := 0, 0
214			var active []*buddy.Block
215			for i := range owned {
216				switch blockPhase(&owned[i]) {
217				case remediationv1alpha1.NodeBlockActive:
218					capacity += usableAddresses(blockAddresses(owned[i].Spec.CIDR))
219					used += owned[i].Status.UsedAddresses
220					if blk := p.Find(owned[i].Spec.CIDR); blk != nil {
221						active = append(active, blk)
222					}
223				case remediationv1alpha1.NodeBlockPending, remediationv1alpha1.NodeBlockDraining:
224					inFlight = true
225				}
226			}
227			if inFlight {
228				plan.Pending = true
229				continue
230			}
231			if !needsGrowth(spec, capacity, used) {
232				continue
233			}
234	
235			headroom := capacityCap(spec, pods) - capacity
236			target := growthTarget(spec, capacity, headroom, minAddrs)
237			if target == 0 {
238				plan.Problems = append(plan.Problems, fmt.Sprintf("node %s reached its capacity cap (%d%% of %d pods)", n.Name, spec.CapacityCapPercent, pods))
239				continue
240			}
241	
242			// Prefer taking the buddy of a block the node already owns: the two
243			// halves then aggregate into one route. Largest block first, and only
244			// if the buddy does not overshoot the target.
245			slices.SortFunc(active, func(a, b *buddy.Block) int { return b.Addresses() - a.Addresses() })
246			grown := false
247			for _, blk := range active {
248				if blk.Addresses() > target || usableAddresses(blk.Addresses()) > headroom {
249					continue
250				}
251				if bd, err := p.AllocateBuddyOf(blk, n.Name); err == nil {
252					plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: bd.CIDR, Reason: reasonGrowInPlace})
253					grown = true
254					break
255				}
256			}
257			if grown {
258				plan.Pending = true
259				continue
260			}
261	
262			got, err := p.AllocateDemand(target, n.Name)
263			if err != nil {
264				plan.Exhausted = true
265				plan.Problems = append(plan.Problems, fmt.Sprintf("cannot grow node %s: %v", n.Name, err))
266				continue
267			}
268			for _, b := range got {
269				plan.New = append(plan.New, plannedBlock{NodeName: n.Name, CIDR: b.CIDR, Reason: reasonGrow})
270			}
271			plan.Pending = true
272		}
273		return plan
274	}
275	
276	func joinProblems(p []string) string {
277		return strings.Join(p, "; ")
278	}
