17	// Package ipam implements the IPAM controller for Problem 1.
18	//
19	// The controller owns the pools. On every reconcile it rebuilds the buddy trees
20	// from the NodeBlock objects (it keeps no private state), decides which blocks
21	// to hand out, and writes them as NodeBlock specs. It writes only spec; the
22	// node agent writes status and applies the blocks to the node's CNI config and
23	// routes. Pod startup never waits on this controller: it works ahead of demand.
24	package ipam
25	
26	import (
27		"context"
28		"fmt"
29		"slices"
30		"strings"
31		"time"
32	
33		corev1 "k8s.io/api/core/v1"
34		apierrors "k8s.io/apimachinery/pkg/api/errors"
35		metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
36		"k8s.io/apimachinery/pkg/runtime"
37		"k8s.io/apimachinery/pkg/types"
38		"k8s.io/client-go/tools/record"
39		ctrl "sigs.k8s.io/controller-runtime"
40		"sigs.k8s.io/controller-runtime/pkg/client"
41		"sigs.k8s.io/controller-runtime/pkg/handler"
42		logf "sigs.k8s.io/controller-runtime/pkg/log"
43		"sigs.k8s.io/controller-runtime/pkg/reconcile"
44	
45		remediationv1alpha1 "CS331-CN-Project-1/operator/api/v1alpha1"
46		"CS331-CN-Project-1/operator/internal/controller/ipam/monitor"
47	)
48	
49	const (
50		// requeueInterval is how often the controller re-reconciles when idle.
51		requeueInterval = 30 * time.Second
52		// requeueBusy is used while a block is Pending, or after a name collision.
53		requeueBusy = 5 * time.Second
54	)
55	
56	// Pool phases.
57	const (
58		phaseReady     = "Ready"
59		phaseExhausted = "Exhausted"
60		phaseDegraded  = "Degraded"
61		phaseInactive  = "Inactive"
62	)
63	
64	// IPAMController reconciles IPPool resources and manages block allocations.
65	type IPAMController struct {
66		client.Client
67		Scheme *runtime.Scheme
68	
69		// Recorder emits Events. It may be nil (tests).
70		Recorder record.EventRecorder
71	
72		// monitor tracks per-node IP usage and detects exhaustion.
73		monitor *monitor.Monitor
74	}
75	
76	// NewIPAMController creates a new IPAM controller.
77	func NewIPAMController(c client.Client, scheme *runtime.Scheme) *IPAMController {
78		return &IPAMController{
79			Client:  c,
80			Scheme:  scheme,
81			monitor: monitor.NewMonitor(c),
82		}
83	}
84	
85	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=ippools,verbs=get;list;watch;create;update;patch;delete
86	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=ippools/status,verbs=get;update;patch
87	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=nodeipallocations,verbs=get;list;watch;create;update;patch;delete
88	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=nodeipallocations/status,verbs=get;update;patch
89	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=nodeblocks,verbs=get;list;watch;create;update;patch;delete
90	// +kubebuilder:rbac:groups=remediation.cn-operator.yuvraj-rathod-1202.github.io,resources=nodeblocks/status,verbs=get;update;patch
91	// +kubebuilder:rbac:groups="",resources=nodes,verbs=get;list;watch
92	// +kubebuilder:rbac:groups="",resources=pods,verbs=get;list;watch
93	// +kubebuilder:rbac:groups="",resources=events,verbs=get;list;watch;create;patch
94	
95	// Reconcile rebuilds the pool from NodeBlocks, plans new blocks, persists them
96	// and updates the IPPool status. It is level-triggered and idempotent.
97	func (r *IPAMController) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
98		logger := logf.FromContext(ctx).WithName("ipam-controller")
99	
100		var ippool remediationv1alpha1.IPPool
101		if err := r.Get(ctx, req.NamespacedName, &ippool); err != nil {
102			return ctrl.Result{}, client.IgnoreNotFound(err)
103		}
104	
105		// Nodes are served by one pool. With several IPPools the earliest created
106		// wins; the others report Inactive instead of competing for nodes.
107		primary, err := r.primaryPool(ctx)
108		if err != nil {
109			return ctrl.Result{}, err
110		}
111		if primary != ippool.Name {
112			return ctrl.Result{}, r.updateStatus(ctx, &ippool, nil, nil, phaseInactive,
113				fmt.Sprintf("IPPool %s is serving the cluster's nodes", primary))
114		}
115	
116		spec := withDefaults(ippool.Spec)
117	
118		var nodes corev1.NodeList
119		if err := r.List(ctx, &nodes); err != nil {
120			return ctrl.Result{}, err
121		}
122		blocks, err := r.blocksFor(ctx, ippool.Name)
123		if err != nil {
124			return ctrl.Result{}, err
125		}
126	
127		plan := planPool(&spec, nodes.Items, blocks)
128	
129		collided := false
130		for _, pb := range plan.New {
131			created, err := r.createBlock(ctx, &ippool, pb)
132			if err != nil {
133				return ctrl.Result{}, err
134			}
135			if !created {
136				// Another writer (or a stale cache) already holds this block.
137				// The next pass rebuilds the tree and picks another one.
138				collided = true
139				continue
140			}
141			logger.Info("Allocated block", "node", pb.NodeName, "cidr", pb.CIDR, "reason", pb.Reason)
142			r.event(&ippool, corev1.EventTypeNormal, "BlockAllocated",
143				fmt.Sprintf("%s block %s to node %s", pb.Reason, pb.CIDR, pb.NodeName))
144		}
145	
146		phase, msg := phaseFor(plan)
147		if plan.Exhausted {
148			r.event(&ippool, corev1.EventTypeWarning, "PoolExhausted", msg)
149		}
150	
151		// Re-list so the status reflects what was just created.
152		if len(plan.New) > 0 {
153			if blocks, err = r.blocksFor(ctx, ippool.Name); err != nil {
154				return ctrl.Result{}, err
155			}
156		}
157		if err := r.updateStatus(ctx, &ippool, plan, blocks, phase, msg); err != nil {
158			if apierrors.IsConflict(err) {
159				// The cache is a write behind our own previous status update.
160				return ctrl.Result{RequeueAfter: time.Second}, nil
161			}
162			return ctrl.Result{}, err
163		}
164	
165		if collided || plan.Pending {
166			return ctrl.Result{RequeueAfter: requeueBusy}, nil
167		}
168		return ctrl.Result{RequeueAfter: requeueInterval}, nil
169	}
170	
171	func phaseFor(plan *poolPlan) (string, string) {
172		switch {
173		case plan.Exhausted:
174			return phaseExhausted, joinProblems(plan.Problems)
175		case len(plan.Problems) > 0:
176			return phaseDegraded, joinProblems(plan.Problems)
177		default:
178			return phaseReady, ""
179		}
180	}
181	
182	// primaryPool returns the name of the IPPool that serves the nodes: the
183	// earliest created, with the name as tie-break.
184	func (r *IPAMController) primaryPool(ctx context.Context) (string, error) {
185		var pools remediationv1alpha1.IPPoolList
186		if err := r.List(ctx, &pools); err != nil {
187			return "", err
188		}
189		items := pools.Items
190		slices.SortFunc(items, func(a, b remediationv1alpha1.IPPool) int {
191			if c := a.CreationTimestamp.Compare(b.CreationTimestamp.Time); c != 0 {
192				return c
193			}
194			return strings.Compare(a.Name, b.Name)
195		})
196		if len(items) == 0 {
197			return "", nil
198		}
199		return items[0].Name, nil
200	}
201	
202	func (r *IPAMController) blocksFor(ctx context.Context, pool string) ([]remediationv1alpha1.NodeBlock, error) {
203		var list remediationv1alpha1.NodeBlockList
204		if err := r.List(ctx, &list); err != nil {
205			return nil, err
206		}
207		out := make([]remediationv1alpha1.NodeBlock, 0, len(list.Items))
208		for _, b := range list.Items {
209			if b.Spec.PoolRef == pool {
210				out = append(out, b)
211			}
212		}
213		return out, nil
214	}
215	
216	// createBlock persists a planned block as a Pending NodeBlock. It returns false
217	// without error when the name is already taken, which is exactly how double
218	// allocation is prevented.
219	func (r *IPAMController) createBlock(ctx context.Context, pool *remediationv1alpha1.IPPool, pb plannedBlock) (bool, error) {
220		nb := &remediationv1alpha1.NodeBlock{
221			ObjectMeta: metav1.ObjectMeta{Name: blockName(pb.CIDR)},
222			Spec: remediationv1alpha1.NodeBlockSpec{
223				NodeName: pb.NodeName,
224				PoolRef:  pool.Name,
225				CIDR:     pb.CIDR,
226			},
227		}
228		// No owner reference on purpose: deleting an IPPool must not garbage-collect
229		// blocks that pods are still using.
230		if err := r.Create(ctx, nb); err != nil {
231			if apierrors.IsAlreadyExists(err) {
232				return false, nil
233			}
234			return false, err
235		}
236		// A crash before this write is harmless: an empty phase counts as Pending.
237		now := metav1.Now()
238		nb.Status.Phase = remediationv1alpha1.NodeBlockPending
239		nb.Status.LastTransitionTime = &now
240		if err := r.Status().Update(ctx, nb); err != nil {
241			return true, client.IgnoreNotFound(err)
242		}
243		return true, nil
244	}
245	
246	func (r *IPAMController) updateStatus(ctx context.Context, pool *remediationv1alpha1.IPPool, plan *poolPlan,
247		blocks []remediationv1alpha1.NodeBlock, phase, msg string) error {
248		st := remediationv1alpha1.IPPoolStatus{Phase: phase, Message: msg}
249		now := metav1.Now()
250		st.LastReconcileTime = &now
251	
252		if plan != nil {
253			stats := plan.Pool.PoolStats()
254			st.TotalAddresses = int64(stats.TotalAddresses)
255			st.AllocatedAddresses = int64(stats.AllocatedAddresses)
256			st.FreeAddresses = int64(stats.FreeAddresses)
257			st.NodeAllocations = summarise(blocks)
258		}
259		if equalStatus(pool.Status, st) {
260			return nil
261		}
262		pool.Status = st
263		return r.Status().Update(ctx, pool)
264	}
265	
266	// equalStatus ignores the timestamp so an idle pool does not write every pass.
267	func equalStatus(a, b remediationv1alpha1.IPPoolStatus) bool {
268		a.LastReconcileTime, b.LastReconcileTime = nil, nil
269		return fmt.Sprint(a) == fmt.Sprint(b)
270	}
271	
272	func summarise(blocks []remediationv1alpha1.NodeBlock) []remediationv1alpha1.NodeAllocationSummary {
273		byNode := map[string]*remediationv1alpha1.NodeAllocationSummary{}
274		for i := range blocks {
275			b := &blocks[i]
276			if blockPhase(b) == remediationv1alpha1.NodeBlockReleased {
277				continue
278			}
279			s := byNode[b.Spec.NodeName]
280			if s == nil {
281				s = &remediationv1alpha1.NodeAllocationSummary{NodeName: b.Spec.NodeName}
282				byNode[b.Spec.NodeName] = s
283			}
284			s.Blocks = append(s.Blocks, b.Spec.CIDR)
285			s.AllocatedIPs += b.Status.UsedAddresses
286			if blockPhase(b) == remediationv1alpha1.NodeBlockActive {
287				s.TotalCapacity += usableAddresses(blockAddresses(b.Spec.CIDR))
288			}
289		}
290		out := make([]remediationv1alpha1.NodeAllocationSummary, 0, len(byNode))
291		for _, s := range byNode {
292			slices.Sort(s.Blocks)
293			if s.TotalCapacity > 0 {
294				s.UtilizationPercent = s.AllocatedIPs * 100 / s.TotalCapacity
295			}
296			out = append(out, *s)
297		}
298		slices.SortFunc(out, func(a, b remediationv1alpha1.NodeAllocationSummary) int {
299			return strings.Compare(a.NodeName, b.NodeName)
300		})
301		return out
302	}
303	
304	func (r *IPAMController) event(obj client.Object, typ, reason, msg string) {
305		if r.Recorder != nil {
306			r.Recorder.Event(obj, typ, reason, msg)
307		}
308	}
309	
310	// SetupWithManager sets up the controller with the Manager. Node and NodeBlock
311	// changes both trigger a reconcile of the pool they belong to.
312	func (r *IPAMController) SetupWithManager(mgr ctrl.Manager) error {
313		r.Recorder = mgr.GetEventRecorderFor("ipam-controller") //nolint:staticcheck
314	
315		allPools := handler.EnqueueRequestsFromMapFunc(func(ctx context.Context, _ client.Object) []reconcile.Request {
316			var pools remediationv1alpha1.IPPoolList
317			if err := r.List(ctx, &pools); err != nil {
318				return nil
319			}
320			reqs := make([]reconcile.Request, 0, len(pools.Items))
321			for _, p := range pools.Items {
322				reqs = append(reqs, reconcile.Request{NamespacedName: types.NamespacedName{Name: p.Name}})
323			}
324			return reqs
325		})
326		ownerPool := handler.EnqueueRequestsFromMapFunc(func(_ context.Context, o client.Object) []reconcile.Request {
327			nb, ok := o.(*remediationv1alpha1.NodeBlock)
328			if !ok || nb.Spec.PoolRef == "" {
329				return nil
330			}
331			return []reconcile.Request{{NamespacedName: types.NamespacedName{Name: nb.Spec.PoolRef}}}
332		})
333	
334		return ctrl.NewControllerManagedBy(mgr).
335			For(&remediationv1alpha1.IPPool{}).
336			Watches(&corev1.Node{}, allPools).
337			Watches(&remediationv1alpha1.NodeBlock{}, ownerPool).
338			Named("ipam").
339			Complete(r)
340	}
