216	// createBlock persists a planned block as a Pending NodeBlock. It returns false
217	// without error when the name is already taken, which is exactly how double
218	// allocation is prevented.
219	func (r *IPAMController) createBlock(ctx context.Context, pool *remediationv1alpha1.IPPool, pb plannedBlock) (bool, error) {
220		nb := &remediationv1alpha1.NodeBlock{
221			ObjectMeta: metav1.ObjectMeta{Name: blockName(pb.CIDR)},
222			Spec: remediationv1alpha1.NodeBlockSpec{
223				NodeName: pb.NodeName,
224				PoolRef:  pool.Name,
225				CIDR:     pb.CIDR,
226			},
227		}
228		// No owner reference on purpose: deleting an IPPool must not garbage-collect
229		// blocks that pods are still using.
230		if err := r.Create(ctx, nb); err != nil {
231			if apierrors.IsAlreadyExists(err) {
232				return false, nil
233			}
234			return false, err
235		}
236		// A crash before this write is harmless: an empty phase counts as Pending.
237		now := metav1.Now()
238		nb.Status.Phase = remediationv1alpha1.NodeBlockPending
239		nb.Status.LastTransitionTime = &now
240		if err := r.Status().Update(ctx, nb); err != nil {
241			return true, client.IgnoreNotFound(err)
242		}
243		return true, nil
244	}
245	
246	func (r *IPAMController) updateStatus(ctx context.Context, pool *remediationv1alpha1.IPPool, plan *poolPlan,
247		blocks []remediationv1alpha1.NodeBlock, phase, msg string) error {
248		st := remediationv1alpha1.IPPoolStatus{Phase: phase, Message: msg}
249		now := metav1.Now()
250		st.LastReconcileTime = &now
251	
252		if plan != nil {
253			stats := plan.Pool.PoolStats()
254			st.TotalAddresses = int64(stats.TotalAddresses)
255			st.AllocatedAddresses = int64(stats.AllocatedAddresses)
256			st.FreeAddresses = int64(stats.FreeAddresses)
257			st.NodeAllocations = summarise(blocks)
258		}
259		if equalStatus(pool.Status, st) {
260			return nil
261		}
262		pool.Status = st
263		return r.Status().Update(ctx, pool)
264	}
265	
266	// equalStatus ignores the timestamp so an idle pool does not write every pass.
267	func equalStatus(a, b remediationv1alpha1.IPPoolStatus) bool {
268		a.LastReconcileTime, b.LastReconcileTime = nil, nil
269		return fmt.Sprint(a) == fmt.Sprint(b)
270	}
271	
272	func summarise(blocks []remediationv1alpha1.NodeBlock) []remediationv1alpha1.NodeAllocationSummary {
273		byNode := map[string]*remediationv1alpha1.NodeAllocationSummary{}
274		for i := range blocks {
275			b := &blocks[i]
276			if blockPhase(b) == remediationv1alpha1.NodeBlockReleased {
277				continue
278			}
279			s := byNode[b.Spec.NodeName]
280			if s == nil {
281				s = &remediationv1alpha1.NodeAllocationSummary{NodeName: b.Spec.NodeName}
282				byNode[b.Spec.NodeName] = s
283			}
284			s.Blocks = append(s.Blocks, b.Spec.CIDR)
285			s.AllocatedIPs += b.Status.UsedAddresses
286			if blockPhase(b) == remediationv1alpha1.NodeBlockActive {
287				s.TotalCapacity += usableAddresses(blockAddresses(b.Spec.CIDR))
288			}
289		}
290		out := make([]remediationv1alpha1.NodeAllocationSummary, 0, len(byNode))
291		for _, s := range byNode {
292			slices.Sort(s.Blocks)
293			if s.TotalCapacity > 0 {
294				s.UtilizationPercent = s.AllocatedIPs * 100 / s.TotalCapacity
295			}
296			out = append(out, *s)
297		}
298		slices.SortFunc(out, func(a, b remediationv1alpha1.NodeAllocationSummary) int {
299			return strings.Compare(a.NodeName, b.NodeName)
300		})
301		return out
302	}
