17	package agent
18	
19	import (
20		"context"
21		"errors"
22		"fmt"
23		"slices"
24		"time"
25	
26		"github.com/go-logr/logr"
27		corev1 "k8s.io/api/core/v1"
28		metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
29		"k8s.io/apimachinery/pkg/types"
30		"k8s.io/client-go/util/retry"
31		"sigs.k8s.io/controller-runtime/pkg/client"
32		logf "sigs.k8s.io/controller-runtime/pkg/log"
33	
34		remediationv1alpha1 "CS331-CN-Project-1/operator/api/v1alpha1"
35	)
36	
37	// Agent keeps one node's routes, CNI config and NodeBlock status in line with
38	// the NodeBlock specs.
39	type Agent struct {
40		Client   client.Client
41		NodeName string
42		Routes   RouteTable
43	
44		// ConfPath is the conflist the runtime reads, e.g. /etc/cni/net.d/10-buddy.conflist.
45		ConfPath string
46		// NetName is the CNI network name.
47		NetName string
48		// LeaseDir is host-local's directory for this network
49		// (<dataDir>/<NetName>); DataDir is the dataDir written to the config.
50		LeaseDir string
51		DataDir  string
52	
53		// PromoteTimeout is how long a Pending block waits for route acks before it
54		// is promoted anyway, so a dead node cannot block a grow.
55		PromoteTimeout time.Duration
56		// Now is the clock; nil means time.Now.
57		Now func() time.Time
58	}
59	
60	func (a *Agent) now() time.Time {
61		if a.Now != nil {
62			return a.Now()
63		}
64		return time.Now()
65	}
66	
67	// Run calls Sync every interval until ctx is cancelled. A failed pass is
68	// logged and retried; the next pass starts from scratch.
69	func (a *Agent) Run(ctx context.Context, interval time.Duration) {
70		logger := logf.FromContext(ctx).WithName("ipam-agent")
71		for {
72			if err := a.Sync(ctx); err != nil {
73				logger.Error(err, "sync failed")
74			}
75			select {
76			case <-ctx.Done():
77				return
78			case <-time.After(interval):
79			}
80		}
81	}
82	
83	// Sync performs one level-triggered pass. Order matters: routes first, then the
84	// CNI config, then the Active phase. Otherwise a pod could be given an address
85	// that nobody can reach.
86	func (a *Agent) Sync(ctx context.Context) error {
87		logger := logf.FromContext(ctx).WithName("ipam-agent")
88	
89		var nodeList corev1.NodeList
90		if err := a.Client.List(ctx, &nodeList); err != nil {
91			return fmt.Errorf("list nodes: %w", err)
92		}
93		var blockList remediationv1alpha1.NodeBlockList
94		if err := a.Client.List(ctx, &blockList); err != nil {
95			return fmt.Errorf("list nodeblocks: %w", err)
96		}
97		nodes, blocks := nodeList.Items, blockList.Items
98	
99		var errs []error
100	
101		// 1. Routes to every other node's blocks.
102		routesOK := true
103		if err := a.syncRoutes(nodes, blocks, logger); err != nil {
104			routesOK = false
105			errs = append(errs, err)
106		}
107	
108		// 2. Acknowledge them, only once they are really installed.
109		if routesOK {
110			for _, name := range AckableBlocks(a.NodeName, blocks) {
111				if err := a.ack(ctx, name); err != nil {
112					errs = append(errs, err)
113				}
114			}
115		}
116	
117		// 3. This node's own blocks.
118		if err := a.syncOwn(ctx, nodes, blocks, routesOK); err != nil {
119			errs = append(errs, err)
120		}
121		return errors.Join(errs...)
122	}
