124	func (a *Agent) syncRoutes(nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock, logger logr.Logger) error {
125		want, problems := DesiredRoutes(a.NodeName, nodes, blocks)
126		for _, p := range problems {
127			logger.Info("route skipped", "reason", p)
128		}
129		have, err := a.Routes.Managed()
130		if err != nil {
131			return fmt.Errorf("list routes: %w", err)
132		}
133		wantSet := map[Route]bool{}
134		for _, r := range want {
135			wantSet[r] = true
136		}
137		haveSet := map[Route]bool{}
138		for _, r := range have {
139			haveSet[r] = true
140		}
141	
142		var errs []error
143		for _, r := range have {
144			if !wantSet[r] {
145				if err := a.Routes.Delete(r); err != nil {
146					errs = append(errs, fmt.Errorf("delete route %s: %w", r.Dst, err))
147					continue
148				}
149				logger.Info("route removed", "dst", r.Dst, "via", r.Gateway)
150			}
151		}
152		for _, r := range want {
153			if !haveSet[r] {
154				if err := a.Routes.Replace(r); err != nil {
155					errs = append(errs, fmt.Errorf("install route %s via %s: %w", r.Dst, r.Gateway, err))
156					continue
157				}
158				logger.Info("route installed", "dst", r.Dst, "via", r.Gateway)
159			}
160		}
161		// A skipped owner (no InternalIP) means the routes are incomplete.
162		if len(problems) > 0 {
163			errs = append(errs, fmt.Errorf("incomplete routes: %v", problems))
164		}
165		return errors.Join(errs...)
166	}
