168	// ack records that this node has the route for a block. Several agents update
169	// the same object, so it retries on conflict.
170	func (a *Agent) ack(ctx context.Context, name string) error {
171		return a.updateStatus(ctx, name, func(b *remediationv1alpha1.NodeBlock) bool {
172			if slices.Contains(b.Status.RoutesAckedBy, a.NodeName) {
173				return false
174			}
175			b.Status.RoutesAckedBy = append(b.Status.RoutesAckedBy, a.NodeName)
176			slices.Sort(b.Status.RoutesAckedBy)
177			return true
178		})
179	}
