181	func (a *Agent) updateStatus(ctx context.Context, name string, mutate func(*remediationv1alpha1.NodeBlock) bool) error {
182		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
183			var b remediationv1alpha1.NodeBlock
184			if err := a.Client.Get(ctx, types.NamespacedName{Name: name}, &b); err != nil {
185				return client.IgnoreNotFound(err)
186			}
187			if !mutate(&b) {
188				return nil
189			}
190			return a.Client.Status().Update(ctx, &b)
191		})
192	}
