194	func (a *Agent) syncOwn(ctx context.Context, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock, routesOK bool) error {
195		logger := logf.FromContext(ctx).WithName("ipam-agent")
196		var own []*remediationv1alpha1.NodeBlock
197		for i := range blocks {
198			if blocks[i].Spec.NodeName == a.NodeName {
199				own = append(own, &blocks[i])
200			}
201		}
202		if len(own) == 0 {
203			return nil
204		}
205	
206		// Active blocks stay in the config. A Pending block joins it only when the
207		// routes are in place everywhere that matters.
208		var inConfig, promote []*remediationv1alpha1.NodeBlock
209		for _, b := range own {
210			switch phaseOf(b) {
211			case remediationv1alpha1.NodeBlockActive:
212				inConfig = append(inConfig, b)
213			case remediationv1alpha1.NodeBlockPending:
214				if routesOK && ReadyToPromote(a.NodeName, b, nodes, a.now(), a.PromoteTimeout) {
215					inConfig = append(inConfig, b)
216					promote = append(promote, b)
217				}
218			}
219		}
220	
221		if len(inConfig) > 0 {
222			cidrs := make([]string, len(inConfig))
223			for i, b := range inConfig {
224				cidrs[i] = b.Spec.CIDR
225			}
226			conf, err := RenderCNIConfig(a.NetName, a.DataDir, cidrs)
227			if err != nil {
228				return err
229			}
230			changed, err := WriteFileIfChanged(a.ConfPath, conf)
231			if err != nil {
232				// Not Active unless the config is really on disk.
233				return fmt.Errorf("write CNI config: %w", err)
234			}
235			if changed {
236				logger.Info("CNI config written", "blocks", cidrs)
237			}
238		}
239	
240		// Usage comes from the lease files of every block this node owns.
241		all := make([]string, len(own))
242		for i, b := range own {
243			all[i] = b.Spec.CIDR
244		}
245		used, err := CountLeases(a.LeaseDir, all)
246		if err != nil {
247			return fmt.Errorf("count leases: %w", err)
248		}
249	
250		promoted := map[string]bool{}
251		for _, b := range promote {
252			promoted[b.Name] = true
253		}
254		var errs []error
255		for _, b := range own {
256			name, n := b.Name, used[b.Spec.CIDR]
257			promoting := promoted[name]
258			if err := a.updateStatus(ctx, name, func(cur *remediationv1alpha1.NodeBlock) bool {
259				changed := false
260				if promoting && phaseOf(cur) == remediationv1alpha1.NodeBlockPending {
261					now := metav1.NewTime(a.now())
262					cur.Status.Phase = remediationv1alpha1.NodeBlockActive
263					cur.Status.LastTransitionTime = &now
264					changed = true
265					logger.Info("block active", "cidr", cur.Spec.CIDR)
266				}
267				if cur.Status.UsedAddresses != n {
268					cur.Status.UsedAddresses = n
269					changed = true
270				}
271				return changed
272			}); err != nil {
273				errs = append(errs, err)
274			}
275		}
276		return errors.Join(errs...)
277	}
