37	// CountLeases counts host-local lease files per block. host-local stores one
38	// file per allocated address, named by the address, in its data directory. This
39	// is the ground truth: it includes leaked leases that no pod accounts for.
40	// Files that are not addresses (last_reserved_ip.*, lock) are ignored.
41	func CountLeases(dir string, cidrs []string) (map[string]int, error) {
42		nets := make(map[string]*net.IPNet, len(cidrs))
43		counts := make(map[string]int, len(cidrs))
44		for _, c := range cidrs {
45			_, n, err := net.ParseCIDR(c)
46			if err != nil {
47				return nil, fmt.Errorf("invalid CIDR %q: %w", c, err)
48			}
49			nets[c] = n
50			counts[c] = 0
51		}
52		entries, err := os.ReadDir(dir)
53		if err != nil {
54			if os.IsNotExist(err) {
55				return counts, nil
56			}
57			return nil, err
58		}
59		for _, e := range entries {
60			ip := net.ParseIP(e.Name())
61			if ip == nil {
62				continue
63			}
64			for c, n := range nets {
65				if n.Contains(ip) {
66					counts[c]++
67					break
68				}
69			}
70		}
71		return counts, nil
72	}
