74	// WriteFileIfChanged writes data to path atomically (temp file + rename) and
75	// reports whether it changed anything. The container runtime watches the
76	// directory, so a half-written file must never be visible.
77	func WriteFileIfChanged(path string, data []byte) (bool, error) {
78		if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
79			return false, nil
80		}
81		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
82			return false, err
83		}
84		tmp, err := os.CreateTemp(filepath.Dir(path), ".buddy-*.tmp")
85		if err != nil {
86			return false, err
87		}
88		defer func() { _ = os.Remove(tmp.Name()) }()
89		if _, err := tmp.Write(data); err != nil {
90			_ = tmp.Close()
91			return false, err
92		}
93		if err := tmp.Close(); err != nil {
94			return false, err
95		}
96		if err := os.Chmod(tmp.Name(), 0o644); err != nil {
97			return false, err
98		}
99		return true, os.Rename(tmp.Name(), path)
100	}
