// starveWindow is how long a "no IP addresses available" event keeps a node
// marked as starved.
const starveWindow = 3 * time.Minute

// starvedNodes returns the nodes whose kubelet recently failed to create a pod
// sandbox because host-local had no address left. That is demand the usage
// counter cannot see, so it forces a grow.
func (r *IPAMController) starvedNodes(ctx context.Context, now time.Time) (map[string]bool, error) {
	var events corev1.EventList
	if err := r.List(ctx, &events); err != nil {
		return nil, err
	}
	out := map[string]bool{}
	for i := range events.Items {
		e := &events.Items[i]
		if !isNoIPEvent(e) {
			continue
		}
		t := e.LastTimestamp.Time
		if t.IsZero() {
			t = e.EventTime.Time
		}
		if t.IsZero() {
			t = e.CreationTimestamp.Time
		}
		if now.Sub(t) > starveWindow {
			continue
		}
		if node := e.Source.Host; node != "" {
			out[node] = true
		} else if e.ReportingInstance != "" {
			out[e.ReportingInstance] = true
		}
	}
	return out, nil
}

func isNoIPEvent(e *corev1.Event) bool {
	return e.Reason == "FailedCreatePodSandBox" && strings.Contains(e.Message, "no IP addresses available")
}

