			Name: "steady", Nodes: 50, MaxPods: 110, Pool: pool16, Duration: 30 * time.Minute,
			Demand: func(*rand.Rand) func(int, time.Duration) int {
				return func(int, time.Duration) int { return 80 }
			},
		},
