		t.Fatalf("second growth: %v", got)
	}
	agg, _ := buddy.Aggregate(got)
	if !reflect.DeepEqual(agg, []string{"10.244.0.0/26"}) {
		t.Fatalf("blocks should aggregate to one route, got %v", agg)
	}
}

