// first blocks before the first CIDR's growth room is spent.
func (p *Pool) AllocateSpread(requestedAddrs int, nodeName string) (*Block, error) {
	p.mu.RLock()
	for _, a := range p.allocators {
		if b, err := a.AllocateSpread(requestedAddrs, nodeName); err == nil {
			p.mu.RUnlock()
			return b, nil
		}
	}
	p.mu.RUnlock()
	return p.Allocate(requestedAddrs, nodeName)
}

