console.log('burst>calm', 'peak', peak, '->', sum(s), 'released', s.log.filter(l=>l.text.includes('released')).length);
// emergency off vs on with demand beyond trigger? starve: demand jumps way above capacity
for (const em of [true,false]) { s = mk(); s.emergencyOn = em; s.nodes.forEach(n=>s.setDemand(n.name,100)); run(s,60); console.log('emergency',em, sum(s)); }
