// no overlap check
const owner = new Map<number,string>(); let bad=0; for (const b of s.blocks) for (let c=b.base;c<b.base+b.size;c+=16){ if(owner.has(c)) bad++; owner.set(c,b.id);} console.log('overlaps', bad);
// pool exhaustion
s = new IpamSim({...(new IpamSim().p), poolSize: 512}); for(let i=0;i<4;i++) s.addNode(); run(s,30); s.nodes.forEach(n=>s.setDemand(n.name,150)); run(s,100); console.log('tiny pool ', sum(s), s.log.filter(l=>l.kind==='warn').slice(-2).map(l=>l.text));
