import { useCallback, useEffect, useRef, useState } from 'react';
import { Boxes, Zap, Rocket, Trash2, RotateCcw, ChevronDown, ChevronUp, CheckCircle2, Circle, Loader2 } from 'lucide-react';
import { aggregate, usable } from '../ipam/engine';
import { policies, scenarios, sweep, liveChecks } from '../ipam/evalData';
import './Project1Demo.css';
import './Project1Live.css';

// Live view of the buddy IPAM operator, built around one demo: spike a node's usage, watch the
// controller add a block, then watch it be drained and released. Everything shown is read from the
// cluster with kubectl (/api/fault/ipam/status); the buttons create real pods or real lease files.
// Stages light up when the cluster data shows them, never on a timer. The offline simulator is
// at /project1/sim.

const CONTROLLER_STALE_SECONDS = 75;
const POLL_MS = 1500;
const POLICY_COLORS = ['#3b82f6', '#f97316', '#10b981', '#e879a9'];
const SPIKE_LEASES = 210;
const REAL_PODS = 20;

interface Blk { name: string; node: string; cidr: string; phase: string; drain: boolean; used: number; acked: string[]; reclaimed: number; base: number; size: number }
interface NodeInfo { name: string; ready: boolean; ip: string; maxPods: number }
interface PodInfo { name: string; ns: string; node: string; ip: string; phase: string }
interface Pool { name: string; spec: any; status: any }
interface FeedItem { id: string; t: number; who: 'controller' | 'agent' | 'cluster' | 'kubelet'; tone: 'add' | 'ok' | 'wait' | 'remove' | 'info' | 'warn'; title: string; detail?: string }
interface Ghost { cidr: string; node: string; until: number }
interface Run { node: string; t0: number; baseCap: number; baseline: string[]; reached: Record<number, number>; newCidr?: string; drainCidr?: string; done: boolean }

const ipToNum = (ip: string) => ip.split('.').reduce((a, o) => ((a << 8) | Number(o)) >>> 0, 0) >>> 0;
const parseCidr = (c: string) => { const [ip, bits] = c.split('/'); return { base: ipToNum(ip), size: 2 ** (32 - Number(bits)) }; };
const phaseOf = (b: Blk) => (b.drain && b.phase === 'Active' ? 'Draining' : b.phase);
const nodeCap = (blocks: Blk[]) => aggregate(blocks.filter(b => b.phase === 'Active' && !b.drain)).reduce((t, r) => t + usable(r.size), 0);
const nodeUsed = (blocks: Blk[]) => blocks.reduce((t, b) => t + b.used, 0);
const fmtClock = (ms: number) => new Date(ms).toLocaleTimeString('en-GB');

const PHASE_MEANING: Record<string, string> = {
  Pending: 'allocated; waiting until every node has a route to it',
  Active: 'routes ready on all nodes; pods can get addresses from it',
  Draining: 'taken out of the CNI config; no new pods; waiting to empty',
  Quarantined: 'empty; routes withdrawn; held back before it can be reused',
};

const STAGES = [
  { title: 'Usage spikes', hint: 'Node fills up' },
  { title: 'Controller adds a block', hint: 'Allocates the next block' },
  { title: 'Block becomes Active', hint: 'Routes ready on all nodes' },
  { title: 'Usage drops', hint: 'Load goes away' },
  { title: 'Block is drained', hint: 'Controller asks to give it back' },
  { title: 'Quarantined', hint: 'Empty; held before reuse' },
  { title: 'Released to the pool', hint: 'Space is free again' },
];

async function getJson(path: string) {
  const r = await fetch(path);
  if (!r.ok) throw new Error(`${path}: ${r.status}`);
  return r.json();
}

export function Project1Demo() {
  const [conn, setConn] = useState<'connecting' | 'ok' | 'error'>('connecting');
  const [err, setErr] = useState('');
  const [nodes, setNodes] = useState<NodeInfo[]>([]);
  const [blocks, setBlocks] = useState<Blk[]>([]);
  const [pods, setPods] = useState<PodInfo[]>([]);
  const [pool, setPool] = useState<Pool | null>(null);
  const [agents, setAgents] = useState({ ready: 0, total: 0 });
  const [crdMissing, setCrdMissing] = useState(false);
  const [now, setNow] = useState(Date.now());
  const [feed, setFeed] = useState<FeedItem[]>([]);
  const [ghosts, setGhosts] = useState<Ghost[]>([]);
  const [run, setRun] = useState<Run | null>(null);
  const [target, setTarget] = useState<string>('');
  const [busy, setBusy] = useState(false);
  const [lastCmd, setLastCmd] = useState<{ ok: boolean; text: string } | null>(null);
  const [more, setMore] = useState<'none' | 'eval' | 'how'>('none');

  const alive = useRef(true);
  const prev = useRef<{ blocks: Map<string, Blk>; used: Map<string, number>; ranges: Map<string, number> } | null>(null);
  const firstSeen = useRef<Map<string, number>>(new Map());
  const phaseSince = useRef<Map<string, { phase: string; at: number }>>(new Map());
  const seenEvents = useRef<Set<string>>(new Set());
  const pageLoaded = useRef(Date.now());
  const runRef = useRef<Run | null>(null);
  runRef.current = run;

  const addFeed = useCallback((items: FeedItem[]) => {
    if (!items.length) return;
    setFeed(f => [...items, ...f].slice(0, 80));
  }, []);

  const refresh = useCallback(async () => {
    try {
      const st = await getJson('/api/fault/ipam/status');
      if (!alive.current) return;
      if (!st.success) throw new Error(st.error ?? 'status failed');
      const t = Date.now();

      const ns: NodeInfo[] = st.nodes.map((n: any) => ({
        name: n.metadata.name,
        ready: n.status.conditions?.find((c: any) => c.type === 'Ready')?.status === 'True',
        ip: n.status.addresses?.find((a: any) => a.type === 'InternalIP')?.address ?? '',
        maxPods: Number(n.status.allocatable?.pods ?? 110),
      })).sort((a: NodeInfo, b: NodeInfo) => a.name.localeCompare(b.name));
      const bs: Blk[] = st.blocks.map((b: any) => {
        const c = parseCidr(b.spec.cidr);
        return {
          name: b.metadata.name, node: b.spec.nodeName, cidr: b.spec.cidr, phase: b.status?.phase || 'Pending',
          drain: !!b.spec.drain, used: b.status?.usedAddresses ?? 0, acked: b.status?.routesAckedBy ?? [],
          reclaimed: b.status?.reclaimedLeases ?? 0, base: c.base, size: c.size,
        } as Blk;
      }).sort((a: Blk, b: Blk) => a.base - b.base);
      const pools = [...st.pools].sort((a: any, b: any) => String(a.metadata.creationTimestamp).localeCompare(String(b.metadata.creationTimestamp)));

      // ---- what changed since the last poll -------------------------------------------------
      const items: FeedItem[] = [];
      const p = prev.current;
      const cur = new Map(bs.map(b => [b.name, b]));
      const usedBy = new Map<string, number>();
      const rangesBy = new Map<string, number>();
      for (const n of ns) {
        const mine = bs.filter(b => b.node === n.name);
        usedBy.set(n.name, nodeUsed(mine));
        rangesBy.set(n.name, aggregate(mine.filter(b => b.phase === 'Active' && !b.drain)).length);
      }
      const newGhosts: Ghost[] = [];
      if (p) {
        for (const b of bs) {
          const before = p.blocks.get(b.name);
          if (!before) { firstSeen.current.set(b.name, t); continue; }
          if (phaseOf(before) !== phaseOf(b)) {
            const ph = phaseOf(b);
            const who = ph === 'Draining' && !before.drain ? 'controller' : 'agent';
            items.push({
              id: `ph-${b.name}-${ph}-${t}`, t, who,
              tone: ph === 'Active' ? 'ok' : ph === 'Pending' ? 'wait' : 'info',
              title: `${b.cidr} on ${b.node}: ${phaseOf(before)} → ${ph}`,
              detail: PHASE_MEANING[ph],
            });
          }
        }
        for (const b of p.blocks.values()) {
          if (!cur.has(b.name)) {
            newGhosts.push({ cidr: b.cidr, node: b.node, until: t + 9000 });
            items.push({ id: `rm-${b.name}-${t}`, t, who: 'controller', tone: 'remove', title: `${b.cidr} released back to the pool`, detail: `${b.node} no longer owns it; any node can be given this space again` });
          }
        }
        for (const n of ns) {
          const a = p.used.get(n.name) ?? 0, z = usedBy.get(n.name) ?? 0;
          if (Math.abs(z - a) >= 5) {
            const cap = nodeCap(bs.filter(b => b.node === n.name));
            items.push({
              id: `use-${n.name}-${t}`, t, who: 'agent', tone: z > a ? 'warn' : 'info',
              title: `${n.name} usage ${a} → ${z}${cap ? ` of ${cap} usable` : ''}`,
              detail: z > a ? 'Agent counted more leases on the node' : 'Leases freed (pods ended or leaked leases reclaimed)',
            });
          }
          const ra = p.ranges.get(n.name) ?? 0, rz = rangesBy.get(n.name) ?? 0;
          const nb = bs.filter(b => b.node === n.name && b.phase === 'Active' && !b.drain).length;
          if (rz !== ra && nb > rz) {
            items.push({ id: `mg-${n.name}-${t}`, t, who: 'agent', tone: 'ok', title: `${n.name}: ${nb} blocks are now served as ${rz} range${rz > 1 ? 's' : ''}`, detail: 'Neighbouring (buddy) blocks merge into one range, so the 3 reserved addresses are paid once' });
          }
        }
      } else {
        for (const b of bs) firstSeen.current.set(b.name, 0);
      }
      for (const b of bs) {
        const ph = phaseOf(b);
        const s = phaseSince.current.get(b.name);
        if (!s || s.phase !== ph) phaseSince.current.set(b.name, { phase: ph, at: p ? t : 0 });
      }
      // controller events (the controller's own words), only those that happened after the page opened
      for (const e of st.events as any[]) {
        const id = e.metadata?.uid ?? `${e.reason}-${e.message}`;
        if (seenEvents.current.has(id)) continue;
        seenEvents.current.add(id);
        const et = Date.parse(e.lastTimestamp || e.eventTime || e.metadata.creationTimestamp);
        if (et < pageLoaded.current - 3000) continue;
        if (e.involvedObject?.kind === 'IPPool') {
          const tone = e.reason === 'BlockAllocated' ? 'add' : e.reason === 'BlockReleased' ? 'remove' : 'info';
          items.push({ id: `ev-${id}`, t: et, who: 'controller', tone, title: e.message, detail: `event ${e.reason}` });
        } else {
          items.push({ id: `ev-${id}`, t: et, who: 'kubelet', tone: 'warn', title: `${e.source?.host ?? 'node'}: pod failed to start, no IP addresses available`, detail: 'The controller treats this as an emergency signal and grows the node' });
        }
      }
      prev.current = { blocks: cur, used: usedBy, ranges: rangesBy };

      // ---- demo run stages, read from the same data ---------------------------------------
      const r = runRef.current;
      let nextRun = r;
      if (r && !r.done) {
        const mine = bs.filter(b => b.node === r.node);
        const used = nodeUsed(mine);
        const el = Math.round((t - r.t0) / 1000);
        const reached = { ...r.reached };
        const mark = (i: number) => { if (reached[i] === undefined) reached[i] = el; };
        let { newCidr, drainCidr } = r;
        if (used >= 0.6 * r.baseCap) mark(0);
        const fresh = mine.find(b => !r.baseline.includes(b.cidr));
        if (fresh) { newCidr = newCidr ?? fresh.cidr; mark(1); }
        const nb = newCidr ? mine.find(b => b.cidr === newCidr) : undefined;
        if (nb && nb.phase === 'Active' && !nb.drain) mark(2);
        if (reached[2] !== undefined && used < 0.15 * r.baseCap) mark(3);
        const dr = mine.find(b => b.drain);
        if (dr) { drainCidr = drainCidr ?? dr.cidr; mark(4); }
        const dq = drainCidr ? mine.find(b => b.cidr === drainCidr) : undefined;
        if (dq && dq.phase === 'Quarantined') mark(5);
        let done = false;
        if (drainCidr && !dq && reached[4] !== undefined) { mark(6); done = true; }
        nextRun = { ...r, reached, newCidr, drainCidr, done };
        if (JSON.stringify(nextRun) !== JSON.stringify(r)) setRun(nextRun);
      }

      setNodes(ns);
      setBlocks(bs);
      setPods(st.pods);
      setPool(pools[0] ? { name: pools[0].metadata.name, spec: pools[0].spec, status: pools[0].status ?? {} } : null);
      setCrdMissing(!!st.crdMissing);
      setAgents(st.agents ? { total: st.agents.desired, ready: st.agents.ready } : { total: 0, ready: 0 });
      if (newGhosts.length) setGhosts(g => [...g.filter(x => x.until > t), ...newGhosts]);
      addFeed(items.sort((a, b) => b.t - a.t));
      setTarget(cur => cur || (ns[1]?.name ?? ns[0]?.name ?? ''));
      setConn('ok');
      setNow(t);
    } catch (e: any) {
      if (!alive.current) return;
      setConn('error');
      setErr(e.message);
    }
  }, [addFeed]);

  useEffect(() => {
    alive.current = true;
    refresh();
    const id = setInterval(refresh, POLL_MS);
    return () => { alive.current = false; clearInterval(id); };
  }, [refresh]);

  const post = async (path: string, body: object) => {
    const r = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    const j = await r.json();
    setLastCmd({ ok: r.ok && j.success !== false, text: `${j.command ?? path}${j.output ? ` — ${String(j.output).slice(0, 90)}` : j.error ? ` — ${j.error}` : ''}` });
    return r.ok && j.success !== false;
  };

  const startSpike = async () => {
    if (!target || busy) return;
    setBusy(true);
    const mine = blocks.filter(b => b.node === target);
    const baseCap = nodeCap(mine) || 253;
    const ok = await post('/api/fault/ipam/leases', { nodeName: target, count: SPIKE_LEASES });
    if (ok) setRun({ node: target, t0: Date.now(), baseCap, baseline: mine.map(b => b.cidr), reached: {}, done: false });
    setBusy(false);
    refresh();
  };
  const runPods = async () => { if (!target || busy) return; setBusy(true); await post('/api/fault/ipam/load', { nodeName: target, pods: REAL_PODS }); setBusy(false); refresh(); };
  const clearLoad = async () => { setBusy(true); await post('/api/fault/ipam/clear-load', {}); setBusy(false); refresh(); };
  const resetView = () => { setRun(null); setFeed([]); setGhosts([]); };

  // ---- derived ---------------------------------------------------------------------------
  const lastRec = pool?.status?.lastReconcileTime ? Math.max(0, Math.round((now - Date.parse(pool.status.lastReconcileTime)) / 1000)) : null;
  const controllerRunning = lastRec !== null && lastRec <= CONTROLLER_STALE_SECONDS;
  const notices: string[] = [];
  if (conn === 'ok') {
    if (crdMissing) notices.push('The IPAM CRDs are not installed. Run: kubectl apply -f operator/config/crd/bases/');
    else if (!pool) notices.push('No IPPool found. Apply operator/config/samples/ipam_sample.yaml (set cidrs and reservedCIDRs for this cluster).');
    else if (!controllerRunning) notices.push('The IPAM controller is not running (no status update for over a minute). Start it: cd operator && go run ./cmd --controllers=ipam');
    if (agents.total === 0) notices.push('The ipam-agent DaemonSet is not deployed: kubectl apply -f operator/deploy/ipam-agent.yaml');
    else if (agents.ready < agents.total) notices.push(`Only ${agents.ready} of ${agents.total} IPAM agents are ready; blocks stay Pending until every node has its routes.`);
  }
  const ready = conn === 'ok' && controllerRunning && agents.total > 0 && agents.ready === agents.total;
  const running = !!run && !run.done;
  const activeGhosts = ghosts.filter(g => g.until > now);
  const targetBlocks = blocks.filter(b => b.node === target);
  const targetCap = nodeCap(targetBlocks);
  const targetUsed = nodeUsed(targetBlocks);
  const currentStage = run ? STAGES.findIndex((_, i) => run.reached[i] === undefined) : -1;
  const elapsed = run ? Math.round(((run.done ? Math.max(...Object.values(run.reached)) * 1000 + run.t0 : now) - run.t0) / 1000) : 0;

  return (
    <div className="pl-page">
      <header className="pl-header">
        <div className="pl-title"><span className="p1-badge">P1</span><Boxes size={20} /> Dynamic pod IP allocation <span className="p1-live"><i /> LIVE</span></div>
        <div className="pl-status">
          <Pill ok={conn === 'ok'} label="Cluster" value={conn === 'ok' ? 'connected' : conn} />
          <Pill ok={controllerRunning} label="Controller" value={controllerRunning ? 'running' : lastRec === null ? 'no status' : 'stopped'} />
          <Pill ok={agents.total > 0 && agents.ready === agents.total} label="Node agents" value={`${agents.ready}/${agents.total}`} />
          <Pill ok={pool?.status?.phase === 'Ready'} label="Pool" value={pool?.status?.phase ?? '—'} />
          <a href="/project2">Problem 2 →</a>
          <a href="/">Cluster view</a>
        </div>
      </header>

      {conn === 'error' && (
        <div className="pl-notice">Cannot read the cluster ({err}). Start the dashboard with the KUBECONFIG of the cluster the operator manages: <code>KUBECONFIG=~/buddy.kubeconfig npm run dev</code></div>
      )}
      {notices.map(n => <div key={n} className="pl-notice">{n}</div>)}

      {/* ---- the demo ---- */}
      <section className="pl-demo">
        <div className="pl-demo-head">
          <div>
            <h2>Demo: a node fills up, then the load goes away</h2>
            <p>Pods get addresses from a block the controller gives each node. Watch it add a block when the node fills up, and take it back when the node is idle.</p>
          </div>
          <div className="pl-controls">
            <label>Node
              <select value={target} onChange={e => setTarget(e.target.value)} disabled={running}>
                {nodes.map(n => <option key={n.name} value={n.name}>{n.name}</option>)}
              </select>
            </label>
            <button className="pl-primary" onClick={startSpike} disabled={!ready || busy || running || !target}>
              {running ? <><Loader2 size={18} className="pl-spin" /> Running… {elapsed}s</> : <><Zap size={18} /> Spike usage (+{SPIKE_LEASES})</>}
            </button>
            <button className="pl-ghost" onClick={runPods} disabled={!ready || busy || !target} title={`Start ${REAL_PODS} real pods on this node`}><Rocket size={15} /> Run {REAL_PODS} real pods</button>
            <button className="pl-ghost" onClick={clearLoad} disabled={busy} title="Delete the real load pods"><Trash2 size={15} /> Remove pods</button>
            <button className="pl-ghost" onClick={resetView} title="Clear this screen"><RotateCcw size={15} /> Clear</button>
          </div>
        </div>
        <ol className="pl-stages">
          {STAGES.map((s, i) => {
            const at = run?.reached[i];
            const state = at !== undefined ? 'done' : i === currentStage && running ? 'now' : 'todo';
            return (
              <li key={s.title} className={`pl-stage ${state}`}>
                <span className="pl-stage-icon">{state === 'done' ? <CheckCircle2 size={22} /> : state === 'now' ? <Loader2 size={22} className="pl-spin" /> : <Circle size={22} />}</span>
                <span className="pl-stage-title">{s.title}</span>
                <span className="pl-stage-sub">{at !== undefined ? `after ${at}s` : s.hint}</span>
              </li>
            );
          })}
        </ol>
        {lastCmd && <div className={`pl-cmd ${lastCmd.ok ? 'ok' : 'bad'}`}>{lastCmd.ok ? '✓' : '✗'} {lastCmd.text}</div>}
      </section>

      <div className="pl-cols">
        {/* ---- left: the node being demoed + the others ---- */}
        <section className="pl-left">
          <div className="pl-node-focus">
            <div className="pl-node-focus-head">
              <h3>{target || '—'}</h3>
              <span className="pl-muted">{nodes.find(n => n.name === target)?.ip} · {pods.filter(p => p.node === target && p.phase === 'Running').length} pods running</span>
            </div>
            <div className="pl-meter" title={`${targetUsed} addresses in use of ${targetCap} usable`}>
              <div className="pl-meter-fill" style={{ width: `${targetCap ? Math.min(100, (100 * targetUsed) / targetCap) : 0}%`, background: targetCap && targetUsed / targetCap > 0.8 ? '#f59e0b' : '#10b981' }} />
              <div className="pl-meter-text"><b>{targetUsed}</b> addresses in use <span>of {targetCap} usable</span></div>
            </div>
            <div className="pl-blocks">
              {targetBlocks.map(b => <BlockTile key={b.name} b={b} isNew={(firstSeen.current.get(b.name) ?? 0) > now - 8000} changed={(phaseSince.current.get(b.name)?.at ?? 0) > now - 3000} />)}
              {activeGhosts.filter(g => g.node === target).map(g => (
                <div key={g.cidr} className="pl-block released"><div className="pl-block-cidr">{g.cidr}</div><div className="pl-badge released">Released</div><div className="pl-block-sub">returned to the pool</div></div>
              ))}
              {!targetBlocks.length && !activeGhosts.length && <div className="pl-muted">No block yet: waiting for the controller.</div>}
            </div>
            {(() => {
              const act = targetBlocks.filter(b => b.phase === 'Active' && !b.drain);
              const rs = aggregate(act);
              return act.length > 1 && rs.length < act.length
                ? <p className="pl-merge">{act.length} neighbouring blocks are served as {rs.length} range ({rs.map(r => `/${32 - Math.log2(r.size)}`).join(', ')}), so the reserved addresses are paid once.</p>
                : null;
            })()}
          </div>

          <h4 className="pl-sub">Other nodes</h4>
          <div className="pl-others">
            {nodes.filter(n => n.name !== target).map(n => {
              const mine = blocks.filter(b => b.node === n.name);
              const cap = nodeCap(mine), used = nodeUsed(mine);
              return (
                <div key={n.name} className="pl-other">
                  <div className="pl-other-name">{n.name}</div>
                  <div className="pl-mini"><div style={{ width: `${cap ? Math.min(100, (100 * used) / cap) : 0}%` }} /></div>
                  <div className="pl-muted">{used}/{cap}</div>
                  <div className="pl-chips">{mine.map(b => <span key={b.name} className={`pl-chip ph-${phaseOf(b)}`}>{b.cidr}</span>)}</div>
                </div>
              );
            })}
          </div>

          <h4 className="pl-sub">Address pool <span className="pl-muted">{pool?.spec?.cidrs?.join(', ')} · {pool?.status?.allocatedAddresses ?? 0} of {pool?.status?.totalAddresses ?? 0} addresses handed out</span></h4>
          {(pool?.spec?.cidrs ?? []).map((c: string) => <PoolStrip key={c} cidr={c} blocks={blocks} target={target} now={now} firstSeen={firstSeen.current} phaseSince={phaseSince.current} />)}
        </section>

        {/* ---- right: what changed ---- */}
        <section className="pl-right">
          <div className="pl-feed-head">
            <h3>What just changed</h3>
            <span className="pl-muted">live from the cluster · newest first</span>
          </div>
          <div className="pl-feed">
            {!feed.length && <div className="pl-empty">Nothing has changed yet.<br />Click <b>Spike usage</b> and watch this list.</div>}
            {feed.map((f, i) => (
              <div key={f.id} className={`pl-item ${f.tone}${i === 0 && now - f.t < 4000 ? ' fresh' : ''}`}>
                <div className="pl-item-top"><span className={`pl-who ${f.who}`}>{f.who}</span><span className="pl-item-time">{fmtClock(f.t)}</span></div>
                <div className="pl-item-title">{f.title}</div>
                {f.detail && <div className="pl-item-detail">{f.detail}</div>}
              </div>
            ))}
          </div>
        </section>
      </div>

      <section className="pl-more">
        <div className="pl-more-bar">
          <button className={more === 'eval' ? 'on' : ''} onClick={() => setMore(more === 'eval' ? 'none' : 'eval')}>{more === 'eval' ? <ChevronUp size={14} /> : <ChevronDown size={14} />} How it compares (simulator)</button>
          <button className={more === 'how' ? 'on' : ''} onClick={() => setMore(more === 'how' ? 'none' : 'how')}>{more === 'how' ? <ChevronUp size={14} /> : <ChevronDown size={14} />} How it works</button>
        </div>
        {more === 'eval' && <EvalView />}
        {more === 'how' && <HowView />}
      </section>
    </div>
  );
}

function Pill({ ok, label, value }: { ok: boolean; label: string; value: string }) {
  return <span className={`pl-pill ${ok ? 'ok' : 'bad'}`}><i />{label}: <b>{value}</b></span>;
}

function BlockTile({ b, isNew, changed }: { b: Blk; isNew: boolean; changed: boolean }) {
  const ph = phaseOf(b);
  const cap = usable(b.size);
  return (
    <div className={`pl-block ph-${ph}${isNew ? ' isnew' : ''}${changed ? ' changed' : ''}`}>
      {isNew && <span className="pl-new">NEW</span>}
      <div className="pl-block-cidr">{b.cidr}</div>
      <div className={`pl-badge ph-${ph}`}>{ph}</div>
      <div className="pl-block-sub">{PHASE_MEANING[ph]}</div>
      <div className="pl-block-used">{b.used} / {cap} used</div>
      {ph === 'Pending' && <div className="pl-block-ack">routes ready on {b.acked.length} of other nodes</div>}
    </div>
  );
}

function PoolStrip({ cidr, blocks, target, now, firstSeen, phaseSince }: {
  cidr: string; blocks: Blk[]; target: string; now: number; firstSeen: Map<string, number>; phaseSince: Map<string, { phase: string; at: number }>;
}) {
  const { base, size } = parseCidr(cidr);
  const cell = Math.max(16, size / 128);
  const n = size / cell;
  const cells: (Blk | null)[] = new Array(n).fill(null);
  blocks.forEach(b => {
    if (b.base < base || b.base >= base + size) return;
    for (let a = b.base; a < b.base + b.size; a += cell) cells[(a - base) / cell] = cells[(a - base) / cell] ?? b;
    if (b.size < cell) cells[(b.base - base) / cell] = b;
  });
  return (
    <div className="pl-strip" role="img" aria-label={`Address map of ${cidr}`}>
      {cells.map((b, i) => {
        const hot = b && ((firstSeen.get(b.name) ?? 0) > now - 6000 || (phaseSince.get(b.name)?.at ?? 0) > now - 3000);
        return <i key={i} className={b ? `on ${b.node === target ? 'mine' : 'other'} ph-${phaseOf(b)}${hot ? ' hot' : ''}` : ''} title={b ? `${b.cidr} → ${b.node} (${phaseOf(b)})` : 'free'} />;
      })}
    </div>
  );
}

