          <button className={more === 'eval' ? 'on' : ''} onClick={() => setMore(more === 'eval' ? 'none' : 'eval')}>{more === 'eval' ? <ChevronUp size={14} /> : <ChevronDown size={14} />} How it compares (simulator)</button>
          <button className={more === 'how' ? 'on' : ''} onClick={() => setMore(more === 'how' ? 'none' : 'how')}>{more === 'how' ? <ChevronUp size={14} /> : <ChevronDown size={14} />} How it works</button>
        </div>
        {more === 'eval' && <EvalView />}
        {more === 'how' && <HowView />}
      </section>
    </div>
  );
}

function Pill({ ok, label, value }: { ok: boolean; label: string; value: string }) {
  return <span className={`pl-pill ${ok ? 'ok' : 'bad'}`}><i />{label}: <b>{value}</b></span>;
}

function Kpi({ label, value, base }: { label: string; value: number | string; base?: number }) {
  const delta = typeof value === 'number' && base !== undefined ? value - base : null;
  return (
    <div className="pl-kpi">
      <div className="pl-kpi-label">{label}</div>
      <div className="pl-kpi-value">{value}{delta !== null && delta !== 0 && <span className={`pl-delta ${delta > 0 ? 'up' : 'down'}`}>{delta > 0 ? '+' : ''}{delta}</span>}</div>
    </div>
  );
}

function StageGroup({ title, labels, state, note }: { title: string; labels: string[]; state: (i: number) => string; note: (i: number) => string }) {
  return (
    <div className="pl-group">
      <div className="pl-group-title">{title}</div>
      <ol className="pl-stages">
        {labels.map((l, i) => {
          const s = state(i);
          return (
            <li key={l} className={`pl-stage ${s}`}>
              <span className="pl-stage-icon">{s === 'done' ? <CheckCircle2 size={20} /> : s === 'now' ? <Loader2 size={20} className="pl-spin" /> : <Circle size={20} />}</span>
              <span className="pl-stage-title">{l}</span>
              <span className="pl-stage-sub">{note(i) || ' '}</span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

function BlockTile({ b, isNew, changed }: { b: Blk; isNew: boolean; changed: boolean }) {
  const ph = phaseOf(b);
  return (
    <div className={`pl-block ph-${ph}${isNew ? ' isnew' : ''}${changed ? ' changed' : ''}`}>
      {isNew && <span className="pl-new">NEW</span>}
      <div className="pl-block-cidr">{b.cidr}</div>
      <div className={`pl-badge ph-${ph}`}>{ph}</div>
      <div className="pl-block-used">{b.used} / {usable(b.size)} used</div>
      <div className="pl-block-sub">{ph === 'Pending' ? `routes on ${b.acked.length} other node${b.acked.length === 1 ? '' : 's'}` : ph === 'Draining' && b.used > 0 ? `waiting for ${b.used} pod${b.used === 1 ? '' : 's'} to end` : PHASE_MEANING[ph]}</div>
    </div>
  );
}

function PoolMap({ pool, blocks, nodes, now, firstSeen, phaseSince }: {
  pool: Pool | null; blocks: Blk[]; nodes: NodeInfo[]; now: number; firstSeen: Map<string, number>; phaseSince: Map<string, number>;
}) {
  const cidr: string | undefined = pool?.spec?.cidrs?.[0];
  if (!cidr || !blocks.length) return null;
  const { base, size } = parseCidr(cidr);
  const inPool = blocks.filter(b => b.base >= base && b.base < base + size);
  if (!inPool.length) return null;
  const lo = Math.min(...inPool.map(b => b.base)), hi = Math.max(...inPool.map(b => b.base + b.size));
  const start = Math.max(base, lo - (lo % 1024));
  const end = Math.min(base + size, Math.max(start + 1024, Math.ceil(hi / 1024) * 1024));
  const cell = Math.max(16, Math.ceil((end - start) / 256 / 16) * 16);
  const n = Math.ceil((end - start) / cell);
  const cells: (Blk | null)[] = new Array(n).fill(null);
  inPool.forEach(b => {
    for (let a = Math.max(b.base, start); a < Math.min(b.base + b.size, end); a += cell) cells[Math.floor((a - start) / cell)] = cells[Math.floor((a - start) / cell)] ?? b;
  });
  return (
    <div className="pl-map">
      <h4 className="pl-sub">Address pool <span className="pl-muted">{cidr} · showing {numToIp(start)} to {numToIp(end - 1)} · 1 square = {cell} addresses · colour = owning node</span></h4>
      <div className="pl-strip" role="img" aria-label="Address pool map">
        {cells.map((b, i) => {
          const idx = b ? nodes.findIndex(x => x.name === b.node) : -1;
          const hot = b && ((firstSeen.get(b.name) ?? 0) > now - 6000 || (phaseSince.get(b.name) ?? 0) > now - 3000);
          return <i key={i} className={b ? `on ph-${phaseOf(b)}${hot ? ' hot' : ''}` : ''} style={b ? { ['--nc' as string]: NODE_COLORS[Math.max(0, idx) % NODE_COLORS.length] } : undefined} title={b ? `${b.cidr} → ${b.node} (${phaseOf(b)})` : `free: ${numToIp(start + i * cell)}`} />;
        })}
      </div>
    </div>
  );
}

function LogView({ lines }: { lines: LogLine[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  useEffect(() => { if (ref.current && stick.current) ref.current.scrollTop = ref.current.scrollHeight; }, [lines.length]);
  return (
    <div className="pl-log" ref={ref} onScroll={e => { const el = e.currentTarget; stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40; }}>
      {!lines.length && <div className="pl-empty">Nothing yet.<br />Click <b>1. Scale out</b>: the request, the command that runs and everything the cluster does in response appear here.</div>}
      {lines.map(l => (
        <div key={l.id} className={`pl-line ${l.tone}`}>
          <span className="pl-line-time">{clock(l.t)}</span>
          <span className={`pl-who ${l.src}`}>{l.src}</span>
          <span className="pl-line-text">{l.text}{l.note && <em>{l.note}</em>}</span>
        </div>
      ))}
    </div>
  );
}

