// Drives headless Firefox over WebDriver BiDi: open the page, click buttons by text, take screenshots.
import fs from 'node:fs';
const [, , scriptPath] = process.argv;
const steps = JSON.parse(fs.readFileSync(scriptPath, 'utf8'));
const ws = new WebSocket('ws://127.0.0.1:9222/session');
let id = 0; const pending = new Map();
ws.onmessage = ev => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
const send = (method, params = {}) => new Promise(res => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
await new Promise(r => (ws.onopen = r));
await send('session.new', { capabilities: {} });
const tree = await send('browsingContext.getTree', {});
const ctx = tree.result.contexts[0].context;
const evalJs = async (expression) => { const r = await send('script.evaluate', { expression, target: { context: ctx }, awaitPromise: true }); return r.result?.result?.value ?? r.error ?? r; };
for (const s of steps) {
  if (s.viewport) await send('browsingContext.setViewport', { context: ctx, viewport: s.viewport });
  if (s.goto) await send('browsingContext.navigate', { context: ctx, url: s.goto, wait: 'complete' });
  if (s.wait) await new Promise(r => setTimeout(r, s.wait));
  if (s.click) console.log('click', s.click, await evalJs(`(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes(${JSON.stringify(s.click)})); if (!b) return 'NOT FOUND'; if (b.disabled) return 'DISABLED'; b.click(); return 'clicked'; })()`));
  if (s.eval) console.log('eval', JSON.stringify(await evalJs(s.eval)).slice(0, 400));
  if (s.shot) { const r = await send('browsingContext.captureScreenshot', { context: ctx, origin: 'document' }); fs.writeFileSync(s.shot, Buffer.from(r.result.data, 'base64')); console.log('shot', s.shot); }
}
ws.close();
process.exit(0);
EOF
