cat > $S/bidi/s1.json <<EOF
[{"viewport":{"width":1500,"height":1000}},{"goto":"http://localhost:5173/project1","wait":4000},{"shot":"$S/ui-a.png"}]
EOF
cd $S/bidi && node drive.mjs s1.json 2>&1 | tail -5

