	out := map[string]int{}
	var firstErr error
	for _, e := range entries {
		ip := net.ParseIP(e.Name())
		if ip == nil || podIPs[e.Name()] {
			continue
		}
		info, err := e.Info()
		if err != nil || now.Sub(info.ModTime()) < minAge {
			continue
		}
