81		if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
82			return false, nil
83		}
84		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
85			return false, err
86		}
87		tmp, err := os.CreateTemp(filepath.Dir(path), ".buddy-*.tmp")
88		if err != nil {
89			return false, err
90		}
91		defer func() { _ = os.Remove(tmp.Name()) }()
92		if _, err := tmp.Write(data); err != nil {
93			_ = tmp.Close()
94			return false, err
95		}
96		if err := tmp.Close(); err != nil {
97			return false, err
98		}
