66	function parseAgentLine(raw: string): { t: number; text: string } | null {
67	  const parts = raw.split('\t');
68	  if (parts.length < 4) return null;
69	  const t = Date.parse(parts[0]);
70	  if (Number.isNaN(t)) return null;
71	  let extra = '';
72	  if (parts[4]) {
73	    try {
74	      const o = JSON.parse(parts[4]);
75	      extra = Object.entries(o).map(([k, v]) => `${k}=${Array.isArray(v) ? (v as unknown[]).join(',') : String(v)}`).join(' ');
76	    } catch { extra = parts[4]; }
77	  }
78	  return { t, text: `${parts[3]}${extra ? ` ${extra}` : ''}` };
79	}
