1	/* Problem 1 live demo page. A plain light theme: white cards, grey text, one muted blue accent.
2	   Status colours are muted and used the same way everywhere:
3	   Active green, Pending amber, Draining brown, Quarantined grey, Released red. */
4	
5	.pl-page {
6	  --bg: #f4f5f7; --card: #ffffff; --line: #dfe3e8; --line-strong: #c5ccd4;
7	  --text: #1f2933; --muted: #667085; --soft: #eef1f4;
8	  --accent: #2f5d9e; --accent-soft: #e7eef8;
9	  --active: #2f7d4f; --active-soft: #e8f3ec;
10	  --pending: #a8650d; --pending-soft: #fbf1e0;
11	  --draining: #8a4b2a; --draining-soft: #f8ebe4;
12	  --quarantined: #667085; --quarantined-soft: #eceff3;
13	  --released: #a93d3a; --released-soft: #f9e8e7;
14	  min-height: 100vh; width: 100vw; background: var(--bg); color: var(--text);
15	  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; font-size: 15px; overflow-y: auto; padding-bottom: 40px;
16	}
17	.pl-page * { box-sizing: border-box; }
18	.pl-page h2, .pl-page h3, .pl-page h4 { margin: 0; }
19	.pl-muted { color: var(--muted); font-size: 0.85rem; }
20	
21	/* header */
22	.pl-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 12px 32px; background: var(--card); border-bottom: 1px solid var(--line); }
23	.pl-title { display: flex; align-items: center; gap: 10px; font-size: 1.1rem; font-weight: 700; }
24	.pl-live { font-size: 0.72rem; font-weight: 600; color: var(--active); background: var(--active-soft); border: 1px solid #cfe5d7; border-radius: 4px; padding: 2px 8px; }
25	.pl-status { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
26	.pl-status a { color: var(--accent); text-decoration: none; font-size: 0.85rem; padding: 4px 8px; border-radius: 6px; }
27	.pl-status a:hover { background: var(--accent-soft); }
28	.pl-pill { display: inline-flex; align-items: center; gap: 7px; font-size: 0.82rem; color: var(--muted); background: var(--soft); border: 1px solid var(--line); border-radius: 6px; padding: 4px 10px; }
29	.pl-pill b { color: var(--text); font-weight: 600; }
30	.pl-pill i { width: 8px; height: 8px; border-radius: 50%; background: var(--released); }
31	.pl-pill.ok i { background: var(--active); }
32	.pl-notice { margin: 14px 32px 0; padding: 10px 14px; border-radius: 8px; background: var(--pending-soft); border: 1px solid #ecd6aa; color: #6b4410; font-size: 0.9rem; }
33	.pl-notice code { background: #fff; padding: 1px 6px; border-radius: 4px; border: 1px solid #ecd6aa; }
34	
35	.pl-main { padding: 20px 32px 0; display: flex; flex-direction: column; gap: 18px; max-width: 1500px; margin: 0 auto; }
36	.pl-card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px 22px; }
37	.pl-card-head { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; flex-wrap: wrap; }
38	.pl-card-head.slim { align-items: baseline; margin-bottom: 14px; }
39	.pl-card-head h2 { font-size: 1.15rem; }
40	.pl-card-head p { margin: 4px 0 0; color: var(--muted); max-width: 680px; line-height: 1.5; font-size: 0.92rem; }
41	.pl-check { display: inline-flex; align-items: center; gap: 8px; font-size: 0.85rem; color: var(--muted); cursor: pointer; }
42	
43	/* scenario buttons */
44	.pl-buttons { display: grid; grid-template-columns: 1.3fr 1.1fr 1fr; gap: 16px; margin-top: 18px; }
45	.pl-scenario { border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; background: #fafbfc; display: flex; flex-direction: column; gap: 8px; }
46	.pl-scenario p { margin: 0; font-size: 0.85rem; color: var(--muted); line-height: 1.5; }
47	.pl-after { flex-direction: column; }
48	.pl-inline { display: flex; gap: 8px; align-items: center; }
49	.pl-scenario select { background: #fff; color: var(--text); border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px; font: inherit; font-size: 0.88rem; }
50	.pl-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: #fff; color: var(--text); border: 1px solid var(--line-strong); border-radius: 8px; padding: 10px 16px; font: inherit; font-size: 0.95rem; font-weight: 600; cursor: pointer; }
51	.pl-btn:hover:not(:disabled) { background: var(--soft); }
52	.pl-btn:disabled { opacity: 0.5; cursor: default; }
53	.pl-btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; font-size: 1.02rem; padding: 12px 20px; }
54	.pl-btn.primary:hover:not(:disabled) { background: #264d85; }
55	.pl-btn.primary:disabled { background: #7d97bd; border-color: #7d97bd; color: #fff; opacity: 1; }
56	.pl-btn.quiet { font-weight: 500; font-size: 0.85rem; color: var(--muted); padding: 7px 12px; }
57	.pl-btn.small { padding: 4px 10px; font-size: 0.78rem; }
58	.pl-spin { animation: pl-spin 1s linear infinite; }
59	@keyframes pl-spin { to { transform: rotate(360deg); } }
60	
61	/* steps */
62	.pl-steps { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 18px; }
63	.pl-group-title { font-size: 0.74rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); font-weight: 700; margin-bottom: 8px; }
64	.pl-stages { list-style: none; display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; padding: 0; margin: 0; }
65	.pl-stage { display: flex; flex-direction: column; gap: 2px; padding: 9px 10px; border-radius: 8px; border: 1px solid var(--line); background: #fff; }
66	.pl-stage-icon { color: var(--line-strong); display: flex; margin-bottom: 2px; }
67	.pl-stage-title { font-weight: 600; font-size: 0.84rem; line-height: 1.25; }
68	.pl-stage-sub { font-size: 0.74rem; color: var(--muted); min-height: 1.1em; }
69	.pl-stage.done { background: var(--active-soft); border-color: #cfe5d7; } .pl-stage.done .pl-stage-icon { color: var(--active); }
70	.pl-stage.now { background: var(--accent-soft); border-color: #bcd0ea; } .pl-stage.now .pl-stage-icon { color: var(--accent); }
71	
72	/* numbers */
73	.pl-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
74	.pl-kpi { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 12px 18px; }
75	.pl-kpi-label { font-size: 0.78rem; color: var(--muted); font-weight: 600; }
76	.pl-kpi-value { font-size: 1.9rem; font-weight: 700; font-variant-numeric: tabular-nums; display: flex; align-items: baseline; gap: 10px; }
77	.pl-delta { font-size: 0.9rem; font-weight: 600; padding: 1px 8px; border-radius: 6px; }
78	.pl-delta.up { color: var(--active); background: var(--active-soft); } .pl-delta.down { color: var(--released); background: var(--released-soft); }
79	
80	/* cluster view */
81	.pl-nodes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; align-items: start; }
82	.pl-node { border: 1px solid var(--line-strong); border-radius: 12px; padding: 14px 14px 16px; background: #fbfbfc; }
83	.pl-node-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
