/* Problem 1 live demo page. A plain light theme: white cards, grey text, one muted blue accent.
   Status colours are muted and used the same way everywhere:
   Active green, Pending amber, Draining brown, Quarantined grey, Released red. */

.pl-page {
  --bg: #f4f5f7; --card: #ffffff; --line: #dfe3e8; --line-strong: #c5ccd4;
  --text: #1f2933; --muted: #667085; --soft: #eef1f4;
  --accent: #2f5d9e; --accent-soft: #e7eef8;
  --active: #2f7d4f; --active-soft: #e8f3ec;
  --pending: #a8650d; --pending-soft: #fbf1e0;
  --draining: #8a4b2a; --draining-soft: #f8ebe4;
  --quarantined: #667085; --quarantined-soft: #eceff3;
  --released: #a93d3a; --released-soft: #f9e8e7;
  min-height: 100vh; width: 100vw; background: var(--bg); color: var(--text);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; font-size: 15px; overflow-y: auto; padding-bottom: 40px;
}
.pl-page * { box-sizing: border-box; }
.pl-page h2, .pl-page h3, .pl-page h4 { margin: 0; }
.pl-muted { color: var(--muted); font-size: 0.85rem; }

/* header */
.pl-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 12px 32px; background: var(--card); border-bottom: 1px solid var(--line); }
.pl-title { display: flex; align-items: center; gap: 10px; font-size: 1.1rem; font-weight: 700; }
.pl-live { font-size: 0.72rem; font-weight: 600; color: var(--active); background: var(--active-soft); border: 1px solid #cfe5d7; border-radius: 4px; padding: 2px 8px; }
.pl-status { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.pl-status a { color: var(--accent); text-decoration: none; font-size: 0.85rem; padding: 4px 8px; border-radius: 6px; }
.pl-status a:hover { background: var(--accent-soft); }
.pl-pill { display: inline-flex; align-items: center; gap: 7px; font-size: 0.82rem; color: var(--muted); background: var(--soft); border: 1px solid var(--line); border-radius: 6px; padding: 4px 10px; }
.pl-pill b { color: var(--text); font-weight: 600; }
.pl-pill i { width: 8px; height: 8px; border-radius: 50%; background: var(--released); }
.pl-pill.ok i { background: var(--active); }
.pl-notice { margin: 14px 32px 0; padding: 10px 14px; border-radius: 8px; background: var(--pending-soft); border: 1px solid #ecd6aa; color: #6b4410; font-size: 0.9rem; }
.pl-notice code { background: #fff; padding: 1px 6px; border-radius: 4px; border: 1px solid #ecd6aa; }

.pl-main { padding: 20px 32px 0; display: flex; flex-direction: column; gap: 18px; max-width: 1500px; margin: 0 auto; }
.pl-card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 20px 22px; }
.pl-card-head { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; flex-wrap: wrap; }
.pl-card-head.slim { align-items: baseline; margin-bottom: 14px; }
.pl-card-head h2 { font-size: 1.15rem; }
.pl-card-head p { margin: 4px 0 0; color: var(--muted); max-width: 680px; line-height: 1.5; font-size: 0.92rem; }
.pl-check { display: inline-flex; align-items: center; gap: 8px; font-size: 0.85rem; color: var(--muted); cursor: pointer; }

/* scenario buttons */
.pl-buttons { display: grid; grid-template-columns: 1.3fr 1.1fr 1fr; gap: 16px; margin-top: 18px; }
.pl-scenario { border: 1px solid var(--line); border-radius: 10px; padding: 14px 16px; background: #fafbfc; display: flex; flex-direction: column; gap: 8px; }
.pl-scenario p { margin: 0; font-size: 0.85rem; color: var(--muted); line-height: 1.5; }
.pl-after { flex-direction: column; }
.pl-inline { display: flex; gap: 8px; align-items: center; }
.pl-scenario select { background: #fff; color: var(--text); border: 1px solid var(--line-strong); border-radius: 8px; padding: 8px 10px; font: inherit; font-size: 0.88rem; }
.pl-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; background: #fff; color: var(--text); border: 1px solid var(--line-strong); border-radius: 8px; padding: 10px 16px; font: inherit; font-size: 0.95rem; font-weight: 600; cursor: pointer; }
.pl-btn:hover:not(:disabled) { background: var(--soft); }
.pl-btn:disabled { opacity: 0.5; cursor: default; }
.pl-btn.primary { background: var(--accent); border-color: var(--accent); color: #fff; font-size: 1.02rem; padding: 12px 20px; }
.pl-btn.primary:hover:not(:disabled) { background: #264d85; }
.pl-btn.primary:disabled { background: #7d97bd; border-color: #7d97bd; color: #fff; opacity: 1; }
.pl-btn.quiet { font-weight: 500; font-size: 0.85rem; color: var(--muted); padding: 7px 12px; }
.pl-btn.small { padding: 4px 10px; font-size: 0.78rem; }
.pl-spin { animation: pl-spin 1s linear infinite; }
@keyframes pl-spin { to { transform: rotate(360deg); } }

