.pl-entry-meta { display: flex; align-items: center; justify-content: space-between; font-size: 0.7rem; color: var(--muted); margin-bottom: 3px; font-variant-numeric: tabular-nums; }
.pl-entry-text { font-size: 0.84rem; line-height: 1.45; }
.pl-entry code { display: block; margin-top: 4px; font-size: 0.7rem; color: var(--muted); background: var(--soft); border-radius: 4px; padding: 2px 6px; white-space: pre-wrap; word-break: break-all; }
.pl-who { font-weight: 700; font-size: 0.66rem; text-transform: uppercase; letter-spacing: 0.06em; padding: 1px 6px; border-radius: 4px; background: var(--soft); }
.pl-who.you { background: #e5e8ee; color: var(--text); } .pl-who.kubernetes { background: var(--soft); color: #475467; }
.pl-who.controller { background: var(--accent-soft); color: var(--accent); } .pl-who.agent { background: var(--good-soft); color: var(--good); }
.pl-who.node { background: var(--warn-soft); color: var(--warn); }
.pl-empty { margin: auto; text-align: center; color: var(--muted); line-height: 1.7; font-size: 0.85rem; padding: 20px; }

@media (max-width: 1100px) {
  .pl-page { height: auto; min-height: 100vh; overflow: auto; }
  .pl-grid { grid-template-columns: 1fr; }
  .pl-log { max-height: 60vh; }
}

