      <div className="pl-pool-line full">
        {mine.map(b => <span key={b.name} className={`seg ph-${phaseOf(b)}`} style={{ ...pct(b.base, b.size, p), background: colorOf(b.node) }} title={`${b.cidr} → ${b.node}`} />)}
        <span className="zoom" style={pct(z.base, z.size, p)} />
      </div>
      <div className="pl-pool-scale"><span>{numToIp(p.base)}</span><span>{numToIp(p.base + p.size - 1)}</span></div>
      <div className="pl-pool-line zoomed">
        {mine.filter(b => b.base >= z.base && b.base < z.base + z.size).map(b => (
          <span key={b.name} className={`seg ph-${phaseOf(b)}`} style={{ ...pct(b.base, b.size, z), background: colorOf(b.node) }} title={`${b.cidr} → ${b.node} (${phaseOf(b)})`}>
