192	      const starved = new Map<string, number>();
193	      let starvedAt = 0;
194	      for (const e of st.events as any[]) {
195	        const id = `${e.metadata?.uid ?? `${e.reason}-${e.message}`}-${e.count ?? 1}`;
196	        if (seen.current.has(id)) continue;
197	        seen.current.add(id);
198	        const et = Date.parse(e.lastTimestamp || e.eventTime || e.metadata.creationTimestamp);
199	        if (et < pageLoaded.current - 3000) continue;
200	        if (e.involvedObject?.kind === 'IPPool') {
201	          if (e.reason === 'PoolReady' || /is serving/.test(e.message)) continue;
202	          const s = controllerSentence(e.reason, String(e.message), short);
203	          items.push({ id: `ev-${id}`, t: et, who: 'controller', tone: s.tone, text: s.text });
204	        } else {
205	          const node = e.source?.host ?? 'a node';
206	          starved.set(node, (starved.get(node) ?? 0) + 1);
207	          starvedAt = Math.max(starvedAt, et);
208	        }
209	      }
210	      for (const [node, count] of starved) {
211	        items.push({ id: `kl-${node}-${t}`, t: starvedAt || t, who: 'node', tone: 'bad', text: `${short(node)} is out of addresses: ${plural(count, 'new pod')} could not get an IP and ${count === 1 ? 'is' : 'are'} waiting. The controller takes this as an urgent signal to grow ${short(node)}.` });
212	      }
213	
214	      // The node agents' own log lines, grouped so one change reads as one sentence.
215	      const routeAdd = new Map<string, { via: string; on: string[]; t: number }>();
216	      const routeDel = new Map<string, { via: string; on: string[]; t: number }>();
217	      for (const a of st.agentLog as { node: string; line: string }[]) {
218	        const id = `ag-${a.node}-${a.line}`;
219	        if (seen.current.has(id)) continue;
220	        seen.current.add(id);
221	        const x = parseAgentLine(a.line);
222	        if (!x || x.t < pageLoaded.current - 3000) continue;
223	        if (x.msg === 'route installed' || x.msg === 'route removed') {
224	          const map = x.msg === 'route installed' ? routeAdd : routeDel;
225	          const g = map.get(x.f.dst) ?? { via: String(x.f.via), on: [] as string[], t: x.t };
226	          g.on.push(short(a.node)); g.t = Math.max(g.t, x.t);
227	          map.set(x.f.dst, g);
228	        } else if (x.msg === 'CNI config written') {
229	          const rs: string[] = x.f.ranges ?? x.f.blocks ?? [];
