231	        } else if (x.msg === 'removed stale CNI masquerade rules') {
232	          items.push({ id, t: x.t, who: 'agent', tone: 'plain', text: `${short(a.node)} cleaned up ${plural(Number(x.f.rules ?? 0), 'old NAT rule')} left behind by deleted pods.` });
233	        } else if (x.msg === 'route skipped') {
234	          items.push({ id, t: x.t, who: 'agent', tone: 'warn', text: `${short(a.node)} could not add a route yet: ${x.f.reason ?? ''}` });
235	        }
236	        // "block Active/Draining/Quarantined" lines are covered by the block's phase change above.
237	      }
