170		want, problems := DesiredRoutes(a.NodeName, nodes, blocks)
171		for _, p := range problems {
172			logger.Info("route skipped", "reason", p)
173		}
174		have, err := a.Routes.Managed()
175		if err != nil {
176			return fmt.Errorf("list routes: %w", err)
177		}
178		wantSet := map[Route]bool{}
179		for _, r := range want {
180			wantSet[r] = true
181		}
182		haveSet := map[Route]bool{}
183		for _, r := range have {
184			haveSet[r] = true
185		}
186	
187		var errs []error
188		for _, r := range have {
189			if !wantSet[r] {
190				if err := a.Routes.Delete(r); err != nil {
191					errs = append(errs, fmt.Errorf("delete route %s: %w", r.Dst, err))
192					continue
193				}
