195			}
196		}
197		for _, r := range want {
198			if !haveSet[r] {
199				if err := a.Routes.Replace(r); err != nil {
200					errs = append(errs, fmt.Errorf("install route %s via %s: %w", r.Dst, r.Gateway, err))
201					continue
202				}
