213	// ack records that this node has the route for a block. Several agents update
214	// the same object, so it retries on conflict.
215	func (a *Agent) ack(ctx context.Context, name string) error {
216		return a.updateStatus(ctx, name, func(b *remediationv1alpha1.NodeBlock) bool {
217			if slices.Contains(b.Status.RoutesAckedBy, a.NodeName) {
218				return false
219			}
220			b.Status.RoutesAckedBy = append(b.Status.RoutesAckedBy, a.NodeName)
221			slices.Sort(b.Status.RoutesAckedBy)
