227		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
228			var b remediationv1alpha1.NodeBlock
229			if err := a.Client.Get(ctx, types.NamespacedName{Name: name}, &b); err != nil {
230				return client.IgnoreNotFound(err)
231			}
232			if !mutate(&b) {
233				return nil
234			}
235			return a.Client.Status().Update(ctx, &b)
236		})
237	}
