239	func (a *Agent) syncOwn(ctx context.Context, nodes []corev1.Node, blocks []remediationv1alpha1.NodeBlock, routesOK bool) error {
240		logger := logf.FromContext(ctx).WithName("ipam-agent")
241		var own []*remediationv1alpha1.NodeBlock
242		for i := range blocks {
243			if blocks[i].Spec.NodeName == a.NodeName {
244				own = append(own, &blocks[i])
245			}
246		}
247		if len(own) == 0 {
248			return nil
249		}
250	
251		// Active blocks stay in the config, except those the controller asked to
252		// drain. A Draining block comes back if the controller withdraws the request.
253		// A Pending block joins only when the routes are in place everywhere that
254		// matters.
255		var inConfig, promote []*remediationv1alpha1.NodeBlock
256		for _, b := range own {
257			switch phaseOf(b) {
258			case remediationv1alpha1.NodeBlockActive:
259				if !b.Spec.Drain {
260					inConfig = append(inConfig, b)
261				}
262			case remediationv1alpha1.NodeBlockDraining:
263				if !b.Spec.Drain {
264					inConfig = append(inConfig, b)
265				}
266			case remediationv1alpha1.NodeBlockPending:
267				if routesOK && ReadyToPromote(a.NodeName, b, nodes, a.now(), a.PromoteTimeout) {
268					inConfig = append(inConfig, b)
269					promote = append(promote, b)
270				}
271			}
272		}
273	
274		configOK := false
275		if len(inConfig) > 0 {
276			cidrs := make([]string, len(inConfig))
277			for i, b := range inConfig {
278				cidrs[i] = b.Spec.CIDR
279			}
280			conf, err := RenderCNIConfig(a.NetName, a.DataDir, cidrs)
281			if err != nil {
282				return err
283			}
284			changed, err := WriteFileIfChanged(a.ConfPath, conf)
285			if err != nil {
286				// Not Active unless the config is really on disk.
287				return fmt.Errorf("write CNI config: %w", err)
288			}
289			if changed {
290				ranges, _ := buddy.Aggregate(cidrs)
291				logger.Info("CNI config written", "blocks", cidrs, "ranges", ranges)
292			}
293			configOK = true
294		}
295	
296		all := make([]string, len(own))
297		for i, b := range own {
298			all[i] = b.Spec.CIDR
299		}
300	
301		// Leaked leases are removed before counting, so usage is not inflated by them.
302		reclaimed := map[string]int{}
303		if a.ReclaimLeaks {
304			var err error
305			if reclaimed, err = a.reclaim(ctx, all); err != nil {
306				logger.Error(err, "lease reclaim failed")
307			}
308		}
309	
310		// Usage comes from the lease files of every block this node owns.
311		used, err := CountLeases(a.LeaseDir, all)
312		if err != nil {
313			return fmt.Errorf("count leases: %w", err)
314		}
315	
316		promoted := map[string]bool{}
317		for _, b := range promote {
318			promoted[b.Name] = true
319		}
320		var errs []error
321		for _, b := range own {
322			name, n := b.Name, used[b.Spec.CIDR]
323			promoting := promoted[name]
324			reclaimedHere := reclaimed[b.Spec.CIDR]
325			if err := a.updateStatus(ctx, name, func(cur *remediationv1alpha1.NodeBlock) bool {
326				changed := false
327				if ph := a.nextPhase(cur, promoting, n, configOK); ph != "" {
328					now := metav1.NewTime(a.now())
329					cur.Status.Phase = ph
330					cur.Status.LastTransitionTime = &now
331					changed = true
332					logger.Info("block "+ph, "cidr", cur.Spec.CIDR)
333				}
334				if cur.Status.UsedAddresses != n {
335					cur.Status.UsedAddresses = n
336					changed = true
337				}
338				if reclaimedHere > 0 {
339					cur.Status.ReclaimedLeases += reclaimedHere
340					changed = true
341				}
342				return changed
343			}); err != nil {
344				errs = append(errs, err)
345			}
346		}
347		return errors.Join(errs...)
348	}
