350	func transitionTime(b *remediationv1alpha1.NodeBlock) time.Time {
351		if b.Status.LastTransitionTime != nil {
352			return b.Status.LastTransitionTime.Time
353		}
354		return b.CreationTimestamp.Time
355	}
356	
357	// reclaim removes the leases in cidrs that no pod on this node holds. A pod
358	// list that comes back empty is not trusted: every node runs at least
359	// kube-proxy, so an empty answer means the list failed, not that all leases
360	// are leaks.
361	func (a *Agent) reclaim(ctx context.Context, cidrs []string) (map[string]int, error) {
362		var pods corev1.PodList
363		if err := a.Client.List(ctx, &pods, client.MatchingFields{"spec.nodeName": a.NodeName}); err != nil {
364			return nil, fmt.Errorf("list pods: %w", err)
365		}
366		if len(pods.Items) == 0 {
367			return nil, nil
368		}
369		return ReclaimLeases(a.LeaseDir, cidrs, PodIPs(pods.Items), a.LeakMinAge, a.now())
370	}
371	
372	// nextPhase is the phase a block moves to, or "" to stay put. configOK says the
373	// CNI config on disk now matches the blocks that should be in it.
374	func (a *Agent) nextPhase(cur *remediationv1alpha1.NodeBlock, promoting bool, used int, configOK bool) string {
375		switch phase := phaseOf(cur); {
376		case promoting && phase == remediationv1alpha1.NodeBlockPending:
377			return remediationv1alpha1.NodeBlockActive
378		case phase == remediationv1alpha1.NodeBlockActive && cur.Spec.Drain && configOK:
379			// The config no longer lists this block.
380			return remediationv1alpha1.NodeBlockDraining
381		case phase == remediationv1alpha1.NodeBlockDraining && !cur.Spec.Drain:
382			return remediationv1alpha1.NodeBlockActive
383		case phase == remediationv1alpha1.NodeBlockDraining && used == 0 && configOK &&
384			a.now().Sub(transitionTime(cur)) >= a.DrainSettle:
385			// Empty and out of the config: routes can be withdrawn and the block held
386			// back until the controller releases it.
387			return remediationv1alpha1.NodeBlockQuarantined
388		}
389		return ""
390	}
391	
392	// cleanNAT removes stale CNI masquerade rules for addresses in the blocks this
393	// node owns, at most once per NATEvery.
394	func (a *Agent) cleanNAT(blocks []remediationv1alpha1.NodeBlock) error {
395		if a.NAT == nil || a.now().Sub(a.lastNAT) < a.NATEvery {
396			return nil
397		}
398		var cidrs []string
399		for i := range blocks {
400			if blocks[i].Spec.NodeName == a.NodeName {
401				cidrs = append(cidrs, blocks[i].Spec.CIDR)
402			}
403		}
404		if len(cidrs) == 0 {
405			return nil
406		}
407		a.lastNAT = a.now()
408		n, err := CleanStaleNAT(a.NAT, cidrs)
409		if n > 0 {
410			logf.Log.WithName("ipam-agent").Info("removed stale CNI masquerade rules", "rules", n)
411		}
412		return err
413	}
