func grown(node, cidr string, lower, upper int, since time.Time) remediationv1alpha1.NodeBlock {
	b := nblock(node, cidr, remediationv1alpha1.NodeBlockActive, lower+upper, since)
	b.Status.HalfUsage = []int{lower, upper}
	return b
}

