type fakeRoutes struct {
	mu      sync.Mutex
	table   map[Route]bool
	failFor string
}

func (f *fakeRoutes) Managed() ([]Route, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]Route, 0, len(f.table))
	for r := range f.table {
		out = append(out, r)
	}
	return out, nil
}

func (f *fakeRoutes) Replace(r Route) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.failFor == r.Dst {
		return errors.New("netlink: operation not permitted")
	}
	f.table[r] = true
	return nil
}

func (f *fakeRoutes) Delete(r Route) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	delete(f.table, r)
	return nil
}

func (f *fakeRoutes) dsts() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]string, 0, len(f.table))
	for r := range f.table {
		out = append(out, r.Dst)
	}
	slices.Sort(out)
	return out
