python3 - <<'EOF'
p='plan.go'
s=open(p).read()
old='''// starved reports whether a failure at time t is newer than every change to the
// node's blocks.
func starved(t time.Time, owned []remediationv1alpha1.NodeBlock) bool {
	if t.IsZero() {
		return false
	}
	for i := range owned {
		if !t.After(transitionTime(&owned[i])) {
			return false
		}
	}
	return true
}'''
new='''// starveGrace is how long after a change to a node's blocks a "no IP
// addresses" failure is still blamed on the old state. During a burst, pod
// sandboxes that read the CNI config before a new block went Active keep
// failing for a moment after it; they succeed on retry and must not count as a
// new shortage. Seen live: 21 such failures one second after a block went
// Active grew a node by a /26 it did not need.
const starveGrace = 5 * time.Second

// starved reports whether a failure at time t is newer than every change to the
// node's blocks, by more than starveGrace.
func starved(t time.Time, owned []remediationv1alpha1.NodeBlock) bool {
	if t.IsZero() {
		return false
	}
	for i := range owned {
		if t.Before(transitionTime(&owned[i]).Add(starveGrace)) {
			return false
		}
	}
	return true
}'''
assert s.count(old)==1; s=s.replace(old,new); open(p,'w').write(s)

p='lifecycle_test.go'
s=open(p).read()
s+='''
func TestFailuresRightAfterAGrowDoNotGrowAgain(t *testing.T) {
	// A block went Active at t0. Pods that read the old config fail one second
	// later; that is not a new shortage. A failure after the grace period is.
	blocks := []remediationv1alpha1.NodeBlock{
		nblock("n1", b0, "Active", 3, t0.Add(-time.Hour)),
		nblock("n1", b1, "Active", 0, t0),
	}
	spec := withDefaults(remediationv1alpha1.IPPoolSpec{CIDRs: []string{"10.244.0.0/22"}})
	late := map[string]time.Time{"n1": t0.Add(time.Second)}
	if p := planPool(&spec, nodes1(), blocks, planInput{Now: t0.Add(2 * time.Second), Starved: late}); len(p.New) != 0 {
		t.Fatalf("grew for failures from before the new block: %v", p.New)
	}
	later := map[string]time.Time{"n1": t0.Add(starveGrace + time.Second)}
	if p := planPool(&spec, nodes1(), blocks, planInput{Now: t0.Add(10 * time.Second), Starved: later}); len(p.New) == 0 {
		t.Fatal("a failure after the grace period must still grow the node")
	}
}
'''
open(p,'w').write(s)
EOF
