    if (poolPhase === 'Exhausted') mark(2);
    // Done when the pool is full and the pods that got an address are running: they fill most of
    // what the nodes hold and the count has settled. Pod start is slow with this many pods, so a
    // quiet spell alone does not mean the rest are waiting for an address.
    const held = ns.reduce((sum, n) => sum + nodeCap(bs.filter(b => b.node === n.name)), 0);
    const settled = t - runningSince.current.t >= 5000;
    if (reached[2] !== undefined && ((running >= 0.85 * held && settled) || el - reached[2] > 120)) mark(3);
  } else {
    if (fresh.length && !mine.some(b => b.phase === 'Pending')) mark(2);
