    if (o.wanted > 0 && mineRunning >= 0.98 * o.wanted) mark(3);
  }
  const done = reached[3] !== undefined;
  if (JSON.stringify(reached) !== JSON.stringify(o.reached) || done !== o.done) next = { ...next, out: { ...o, reached, done } };
}
