function LogView({ lines }: { lines: LogLine[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  useEffect(() => { if (ref.current && stick.current) ref.current.scrollTop = ref.current.scrollHeight; }, [lines.length]);
  return (
    <div className="pl-log" ref={ref} onScroll={e => { const el = e.currentTarget; stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 40; }}>
      {!lines.length && <div className="pl-empty">Nothing has happened yet.<br />Press <b>Fill the IP pool</b> and every step the cluster takes is written here.</div>}
      {lines.map(l => (
        <div key={l.id} className={`pl-entry ${l.tone}`}>
          <div className="pl-entry-meta"><span className={`pl-who ${l.who}`}>{WHO_LABEL[l.who]}</span><span>{clock(l.t)}</span></div>
          <div className="pl-entry-text">{l.text}</div>
          {l.detail && <code>{l.detail}</code>}
        </div>
      ))}
    </div>
  );
}
