func needsGrowth(spec *remediationv1alpha1.IPPoolSpec, capacity, used int) bool {
	threshold := max(spec.TriggerFloor, capacity*(100-spec.ExpandThresholdPercent)/100)
	return capacity-used < threshold
}
func growthTarget(spec *remediationv1alpha1.IPPoolSpec, capacity, headroom, minBlock int) int {
	want := max((capacity*spec.GrowthPercent+99)/100, minBlock)
	target := nextPow2(want)
	for target > minBlock && usableAddresses(target) > headroom {
		target >>= 1
	}
	if usableAddresses(target) > headroom {
		return 0
	}
	return target
}
func (plan *poolPlan) growNode(spec *remediationv1alpha1.IPPoolSpec, p *buddy.Pool, node string, pods, capacity, minAddrs int, active []*buddy.Block) {
	headroom := capacityCap(spec, pods) - capacity
	target := growthTarget(spec, capacity, headroom, minAddrs)
	if target == 0 {
		plan.Problems = append(plan.Problems, fmt.Sprintf("node %s reached its capacity cap (%d%% of %d pods)", node, spec.CapacityCapPercent, pods))
		return
	}

	// Prefer the free buddy of a block the node already owns. A buddy no larger
	// than the target is taken whole, and the two halves aggregate into one
	// range and one route. A larger buddy gives only the target's worth, from
	// the piece next to the node's block; the rest stays free beside the node
	// for its next grow. Largest block first.
	slices.SortFunc(active, func(a, b *buddy.Block) int { return b.Addresses() - a.Addresses() })
	for _, blk := range active {
		if usableAddresses(min(blk.Addresses(), target)) > headroom {
			continue
		}
		if got, err := p.AllocateFromBuddy(blk, target, node); err == nil {
			reason := reasonGrowInPlace
			if got.Addresses() < blk.Addresses() {
				reason = reasonGrowBeside
			}
			plan.New = append(plan.New, plannedBlock{NodeName: node, CIDR: got.CIDR, Reason: reason})
			plan.Pending = true
			return
		}
	}

	got, err := p.AllocateDemand(target, node)
	if err != nil {
		plan.Exhausted = true
		plan.Problems = append(plan.Problems, fmt.Sprintf("cannot grow node %s: %v", node, err))
		return
	}
	for _, b := range got {
		plan.New = append(plan.New, plannedBlock{NodeName: node, CIDR: b.CIDR, Reason: reasonGrow})
	}
	plan.Pending = true
}
